ENGINE_ROOM_HTML = '<!doctype html>\n<html lang="en">\n<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <meta name="color-scheme" content="light dark">\n  <title>SessionBuddy Engine Room</title>\n  <link rel="stylesheet" href="/engine-room/assets/console.css?v=engine-room-1">\n  <script src="/engine-room/assets/console.js?v=engine-room-1" defer></script>\n</head>\n<body>\n  <a class="skip-link" href="#content">Skip to content</a>\n  <header>\n    <p class="eyebrow">SessionBuddy · operations</p>\n    <h1>Engine Room</h1>\n    <p>This surface reports only safe operational metadata. It contains no event, speaker, or submission data.</p>\n    <span id="classification-badge" class="badge badge-warning">Synthetic / local</span>\n  </header>\n  <main id="content" tabindex="-1">\n    <div id="notice" class="notice" role="status" aria-live="polite">Loading current request evidence…</div>\n    <section aria-labelledby="runtime-title">\n      <h2 id="runtime-title">Runtime status</h2>\n      <dl class="metric-grid">\n        <div><dt>API</dt><dd id="api-state">Checking…</dd></div>\n        <div><dt>Environment</dt><dd id="environment">Unknown</dd></div>\n        <div><dt>Runtime</dt><dd id="runtime">Unknown</dd></div>\n        <div><dt>Request ID</dt><dd id="request-id">Unavailable</dd></div>\n      </dl>\n    </section>\n    <section aria-labelledby="timing-title">\n      <h2 id="timing-title">Current request timing</h2>\n      <p class="context">A single live request, not benchmark history. Units: milliseconds.</p>\n      <dl id="timings" class="metric-grid"><div><dt>Total</dt><dd>Awaiting response</dd></div></dl>\n    </section>\n    <section aria-labelledby="slo-title">\n      <h2 id="slo-title">API performance contracts</h2>\n      <p class="context">Definitions only · no live sample set · p95 budget.</p>\n      <div class="table-scroll" tabindex="0" aria-label="Scrollable API performance contracts"><table>\n        <thead><tr><th scope="col">Route</th><th scope="col">Owner</th><th scope="col">p95</th><th scope="col">Max errors</th><th scope="col">Benchmark</th></tr></thead>\n        <tbody id="slos"><tr><td colspan="5">Loading…</td></tr></tbody>\n      </table></div>\n    </section>\n    <section aria-labelledby="coverage-title">\n      <h2 id="coverage-title">Observability coverage</h2>\n      <p class="context">Missing and planned signals are intentionally distinct from healthy zero values.</p>\n      <ul id="coverage" class="coverage-list"><li>Loading…</li></ul>\n    </section>\n    <section aria-labelledby="progress-title">\n      <h2 id="progress-title">Build progress</h2>\n      <p class="context">What is implemented now and what the next product slice will add.</p>\n      <div class="table-scroll" tabindex="0" aria-label="Scrollable build progress"><table>\n        <thead><tr><th scope="col">Area</th><th scope="col">Capability</th><th scope="col">State</th><th scope="col">Evidence</th></tr></thead>\n        <tbody id="build-progress"><tr><td colspan="4">Loading…</td></tr></tbody>\n      </table></div>\n    </section>\n    <section aria-labelledby="review-title">\n      <h2 id="review-title">Local release review</h2>\n      <p class="context">Open the seeded product surfaces. Event-scoped admin links appear after creating or selecting an event.</p>\n      <nav aria-label="Local product review" class="review-links">\n        <a href="/admin/programs">Programs and submissions</a>\n        <a href="/speaker">Speaker portal</a>\n        <a href="/reviews">Evaluator workspace</a>\n        <a href="/api/v1/openapi.json">API contract</a>\n      </nav>\n    </section>\n    <aside aria-labelledby="debug-title">\n      <h2 id="debug-title">Debug path</h2>\n      <ol>\n        <li>Record environment, route template, request ID, and visible symptom.</li>\n        <li>Split browser, network, Worker, authorization, and database time.</li>\n        <li>Compare equivalent seed, device, concurrency, and cold/warm conditions.</li>\n        <li>Reproduce with synthetic data and add a regression test before fixing.</li>\n      </ol>\n      <p><a href="/api/v1/openapi.json">Inspect the OpenAPI contract</a></p>\n    </aside>\n  </main>\n  <noscript>This console needs JavaScript to fetch current, non-sensitive runtime evidence.</noscript>\n</body>\n</html>\n'

CONSOLE_CSS = ':root { font-family: system-ui, -apple-system, "Segoe UI", sans-serif; color: #14211c; background: #f3f6f4; }\n* { box-sizing: border-box; }\nbody { margin: 0; line-height: 1.5; }\nheader, main { width: calc(100% - 2rem); max-width: 72rem; margin-left: auto; margin-right: auto; margin-inline: auto; }\nheader { padding: 3.5rem 0 1.5rem; }\nh1 { max-width: 15ch; margin: .15rem 0 .5rem; font-size: 3rem; font-size: clamp(2rem, 7vw, 4rem); line-height: 1; }\nh2 { margin-top: 0; }\n.eyebrow { text-transform: uppercase; letter-spacing: .12em; font-weight: 700; color: #27624d; }\n.badge { display: inline-block; padding: .3rem .65rem; border-radius: 999px; font-weight: 700; }\n.badge-warning { color: #694400; background: #ffe19a; }\nmain { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1rem; padding-bottom: 4rem; }\nsection, aside, .notice { padding: 1.25rem; border: 1px solid #cbd8d1; border-radius: .8rem; background: #fff; }\n.notice { grid-column: 1 / -1; }\n.notice.error { border-color: #b63131; color: #7f1d1d; }\n.metric-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: .75rem; }\n.metric-grid div { padding: .85rem; background: #edf4f0; border-radius: .5rem; min-width: 0; }\ndt { color: #496157; font-size: .85rem; }\ndd { margin: .15rem 0 0; font-weight: 700; overflow-wrap: break-word; overflow-wrap: anywhere; }\n.context { color: #52645c; }\n.table-scroll { overflow-x: auto; }\ntable { width: 100%; border-collapse: collapse; }\nth, td { padding: .65rem; text-align: left; border-bottom: 1px solid #dce5e0; }\n.coverage-list { padding: 0; list-style: none; }\n.coverage-list li { display: flex; justify-content: space-between; gap: .75rem; padding: .65rem 0; border-bottom: 1px solid #dce5e0; }\n.review-links { display: grid; gap: .6rem; }\n.review-links a { min-height: 2.75rem; display: flex; align-items: center; padding: .55rem .7rem; border: 1px solid #cbd8d1; border-radius: .5rem; text-decoration: none; }\n.state-available { color: #17613e; }\n.state-planned { color: #765300; }\n.state-missing { color: #9a2929; }\na { color: #075e48; }\na:focus { outline: 3px solid #e69b00; outline-offset: 3px; }\na:focus:not(:focus-visible) { outline: none; }\na:focus-visible { outline: 3px solid #e69b00; outline-offset: 3px; }\n.skip-link { position: absolute; left: .5rem; top: -4rem; padding: .5rem; background: #fff; z-index: 1; }\n.skip-link:focus { top: .5rem; }\n@media (max-width: 48rem) { main { grid-template-columns: 1fr; } .metric-grid { grid-template-columns: 1fr; } header { padding-top: 2rem; } }\n@media (prefers-reduced-motion: reduce) { *, *::before, *::after { scroll-behavior: auto !important; } }\n@media (prefers-color-scheme: dark) { :root { color: #edf6f1; background: #101814; } section, aside, .notice { background: #18251f; border-color: #365247; } .metric-grid div { background: #22362d; } .context, dt { color: #b9cec4; } th, td, .coverage-list li { border-color: #365247; } a { color: #7ad7b5; } .state-available { color: #83d9b5; } .state-planned { color: #f2c96d; } .state-missing { color: #ff9696; } }\n'

CONSOLE_JS = '(() => {\n  "use strict";\n  const byId = (id) => document.getElementById(id);\n  const text = (value) => document.createTextNode(String(value));\n  const cell = (tag, value) => { const node = document.createElement(tag); node.append(text(value)); return node; };\n  const vitals = { lcp_ms: null, inp_ms: null, cls: 0, fcp_ms: null };\n\n  function observeVitals() {\n    if (!("PerformanceObserver" in window)) return;\n    const watch = (type, callback) => {\n      try { new PerformanceObserver(callback).observe({ type, buffered: true }); } catch (_) { /* unsupported */ }\n    };\n    watch("largest-contentful-paint", (list) => {\n      const entries = list.getEntries();\n      if (entries.length) vitals.lcp_ms = entries[entries.length - 1].startTime;\n    });\n    watch("event", (list) => {\n      for (const entry of list.getEntries()) vitals.inp_ms = Math.max(vitals.inp_ms || 0, entry.duration);\n    });\n    watch("layout-shift", (list) => {\n      for (const entry of list.getEntries()) if (!entry.hadRecentInput) vitals.cls += entry.value;\n    });\n    watch("paint", (list) => {\n      const fcp = list.getEntries().find((entry) => entry.name === "first-contentful-paint");\n      if (fcp) vitals.fcp_ms = fcp.startTime;\n    });\n  }\n\n  function parseServerTiming(header) {\n    if (!header) return [];\n    return header.split(",").flatMap((part) => {\n      const match = part.trim().match(/^([a-z]+);dur=([0-9.]+)$/);\n      return match ? [{ name: match[1], duration: Number(match[2]) }] : [];\n    });\n  }\n\n  function telemetryDraft(requestId, criticalApiMs) {\n    const navigation = performance.getEntriesByType("navigation")[0];\n    const width = window.innerWidth;\n    return {\n      schema_version: 1,\n      page_template: "/engine-room",\n      navigation_type: navigation?.type || "unknown",\n      device_class: width < 640 ? "mobile" : width < 1024 ? "tablet" : "desktop",\n      sampled: false,\n      lcp_ms: vitals.lcp_ms,\n      inp_ms: vitals.inp_ms,\n      cls: vitals.cls,\n      ttfb_ms: navigation ? Math.max(0, navigation.responseStart) : null,\n      fcp_ms: vitals.fcp_ms,\n      critical_api_ms: criticalApiMs,\n      api_request_id: requestId || null\n    };\n  }\n\n  async function load() {\n    const started = performance.now();\n    try {\n      const response = await fetch("/api/v1/engine-room/status", { headers: { accept: "application/json" } });\n      if (!response.ok) throw new Error(`Status API returned ${response.status}`);\n      const model = await response.json();\n      const requestId = response.headers.get("x-request-id");\n      const requestMs = Math.max(0, performance.now() - started);\n      byId("api-state").textContent = "Healthy response";\n      byId("environment").textContent = `${model.environment} · ${model.data_classification}`;\n      byId("classification-badge").textContent = model.data_classification.replace("/", " / ");\n      byId("runtime").textContent = model.runtime;\n      byId("request-id").textContent = requestId || "Unavailable";\n      byId("notice").textContent = "Current API evidence loaded. Historical charts are not connected yet.";\n\n      const timings = parseServerTiming(response.headers.get("server-timing"));\n      const timingList = byId("timings"); timingList.replaceChildren();\n      (timings.length ? timings : [{ name: "round trip", duration: requestMs }]).forEach((item) => {\n        const wrap = document.createElement("div");\n        wrap.append(cell("dt", item.name), cell("dd", `${item.duration.toFixed(1)} ms`));\n        timingList.append(wrap);\n      });\n\n      const sloBody = byId("slos"); sloBody.replaceChildren();\n      model.slos.forEach((slo) => {\n        const row = document.createElement("tr");\n        [slo.route, slo.owner, `${slo.p95_ms} ms`, `${(slo.error_rate_max * 100).toFixed(2)}%`, slo.benchmark]\n          .forEach((value) => row.append(cell("td", value)));\n        sloBody.append(row);\n      });\n\n      const coverage = byId("coverage"); coverage.replaceChildren();\n      model.coverage.forEach((item) => {\n        const row = document.createElement("li");\n        row.append(cell("span", `${item.signal} · ${item.source}`));\n        const state = cell("strong", item.state); state.className = `state-${item.state}`;\n        row.append(state); coverage.append(row);\n      });\n\n      const progress = byId("build-progress"); progress.replaceChildren();\n      model.build_progress.forEach((item) => {\n        const row = document.createElement("tr");\n        [item.area, item.capability, item.state.replace("_", " "), item.evidence]\n          .forEach((value) => row.append(cell("td", value)));\n        progress.append(row);\n      });\n\n      // Privacy-safe payload is intentionally not transmitted until an audited,\n      // rate-limited ingestion endpoint exists. It is available to integration tests.\n      window.__sessionbuddyTelemetryDraft = telemetryDraft(requestId, requestMs);\n    } catch (error) {\n      byId("api-state").textContent = "Unavailable";\n      byId("notice").textContent = `Telemetry missing: ${error.message}`;\n      byId("notice").classList.add("error");\n    }\n  }\n  observeVitals();\n  load();\n})();\n'

CFP_INTEGRATION_HTML = '<!doctype html>\n<html lang="en">\n<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <title>SessionBuddy · CFP integration</title>\n  <link rel="stylesheet" href="/cfp-integration/assets/cfp_integration.css?v=3">\n  <script src="/cfp-integration/assets/cfp_integration.js?v=3" defer></script>\n</head>\n<body>\n  <header><p class="eyebrow">SessionBuddy · local synthetic demo</p><h1>Call for speakers</h1><p>Create, publish, submit, and review one complete workflow.</p></header>\n  <main>\n    <div id="status" class="status" role="status" aria-live="polite">Signed out. Admin actions are locked.</div>\n    <section class="session-panel"><h2>Local authentication</h2><p>This development-only button creates a real D1 session with the organization-admin role. The production sign-in method is still under review.</p><button id="sign-in">Sign in as local demo admin</button><button id="refresh-session" disabled>Rotate session</button><button id="logout" disabled>Log out</button></section>\n    <section><h2>1. Create a program</h2><form id="program-form"><label>Program name<input name="name" value="AI Engineer Summit CFP" required maxlength="200"></label><button disabled>Create program</button></form><pre id="program-result">Sign in to continue</pre></section>\n    <section><h2>2. Publish the form</h2><form id="publish-form"><label>Public slug<input name="slug" value="ai-engineer-summit" required pattern="[a-z0-9-]+"></label><label>Welcome text<textarea name="welcome_text" required>Share the session you want to bring to the AI Engineer community.</textarea></label><button disabled>Publish form</button></form><pre id="form-result">Waiting for a program</pre></section>\n    <section><h2>3. Submit a proposal</h2><form id="submission-form"><label>Speaker name<input name="speaker_name" value="Demo Speaker" required></label><label>Proposal title<input name="proposal_title" value="Building observable AI systems" required></label><label>Abstract<textarea name="proposal_abstract" required>A practical session about measuring reliability and performance across an AI application.</textarea></label><button disabled>Submit proposal</button></form><pre id="submission-result">Waiting for a published form</pre></section>\n    <section><h2>4. Authorized admin view</h2><button id="refresh" disabled>Refresh submissions</button><div class="table-scroll"><table><thead><tr><th>Speaker</th><th>Proposal</th><th>Status</th></tr></thead><tbody id="submissions"><tr><td colspan="3">No submissions yet</td></tr></tbody></table></div></section>\n  </main>\n</body>\n</html>\n'

CFP_INTEGRATION_CSS = ':root { font-family: system-ui, -apple-system, "Segoe UI", sans-serif; color: #17211c; background: #eef3f0; }\n* { box-sizing: border-box; }\nbody { margin: 0; line-height: 1.5; }\nheader, main { width: calc(100% - 2rem); max-width: 76rem; margin: auto; }\nheader { padding: 3rem 0 1.5rem; }\nh1 { margin: .1rem 0; font-size: clamp(2.2rem, 7vw, 4.5rem); line-height: 1; }\n.eyebrow { color: #176048; text-transform: uppercase; letter-spacing: .12em; font-weight: 800; }\nmain { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1rem; padding-bottom: 4rem; }\nsection, .status { background: white; border: 1px solid #cbd8d1; border-radius: .8rem; padding: 1.25rem; }\n.status { grid-column: 1 / -1; }\nform { display: grid; gap: .8rem; }\nlabel { display: grid; gap: .25rem; font-weight: 700; }\ninput, textarea, button { font: inherit; }\ninput, textarea { width: 100%; padding: .7rem; border: 1px solid #8ca095; border-radius: .4rem; }\ntextarea { min-height: 7rem; resize: vertical; }\nbutton { width: fit-content; padding: .65rem 1rem; border: 0; border-radius: .4rem; color: white; background: #075e48; font-weight: 800; cursor: pointer; }\nbutton:disabled { opacity: .45; cursor: not-allowed; }\npre { white-space: pre-wrap; overflow-wrap: anywhere; padding: .7rem; background: #edf4f0; border-radius: .4rem; }\n.table-scroll { overflow-x: auto; }\ntable { width: 100%; border-collapse: collapse; margin-top: .75rem; }\nth, td { padding: .6rem; border-bottom: 1px solid #dce5e0; text-align: left; }\n@media (max-width: 48rem) { main { grid-template-columns: 1fr; } }\n'

CFP_INTEGRATION_JS = '(() => {\n  "use strict";\n  const state = { context: null, csrfToken: null, program: null, form: null };\n  const byId = (id) => document.getElementById(id);\n  const jsonHeaders = () => ({ "content-type": "application/json" });\n  const adminHeaders = () => ({ ...jsonHeaders(), "x-csrf-token": state.csrfToken });\n  const key = () => `${crypto.randomUUID()}-${crypto.randomUUID()}`;\n  async function api(path, options = {}) {\n    const started = performance.now();\n    const response = await fetch(path, options);\n    if (response.status === 204) return null;\n    const body = await response.json();\n    if (!response.ok) {\n      const error = new Error(body.error?.message || `Request failed (${response.status})`);\n      error.status = response.status;\n      throw error;\n    }\n    const navigation = performance.getEntriesByType("navigation")[0];\n    const width = window.innerWidth;\n    window.__sessionbuddyTelemetryDraft = {\n      schema_version: 1,\n      page_template: "/cfp-integration",\n      navigation_type: navigation?.type || "unknown",\n      device_class: width < 640 ? "mobile" : width < 1024 ? "tablet" : "desktop",\n      sampled: false,\n      lcp_ms: null,\n      inp_ms: null,\n      cls: null,\n      ttfb_ms: navigation ? Math.max(0, navigation.responseStart) : null,\n      fcp_ms: null,\n      route_transition_ms: null,\n      critical_api_ms: Math.max(0, performance.now() - started),\n      api_request_id: response.headers.get("x-request-id")\n    };\n    return body;\n  }\n  function values(form) { return Object.fromEntries(new FormData(form).entries()); }\n  function show(id, value) { byId(id).textContent = JSON.stringify(value, null, 2); }\n  async function signIn() {\n    try {\n      byId("sign-in").disabled = true;\n      byId("status").textContent = "Creating authenticated local session…";\n      const session = await api("/api/v1/demo/session", { method: "POST" });\n      state.context = { organization_id: session.organization_id, event_id: session.event_id };\n      state.csrfToken = session.csrf_token;\n      byId("status").textContent = "Authenticated local organization admin session ready.";\n      byId("program-form").querySelector("button").disabled = false;\n      byId("program-result").textContent = "Ready to create a program";\n      byId("sign-in").textContent = "Refresh organization-admin session";\n      byId("sign-in").disabled = false;\n      byId("refresh-session").disabled = false;\n      byId("logout").disabled = false;\n    } catch (error) {\n      byId("status").textContent = error.message;\n      byId("sign-in").disabled = false;\n    }\n  }\n  byId("program-form").addEventListener("submit", async (event) => {\n    event.preventDefault();\n    try {\n      state.program = await api("/api/v1/admin/programs", { method: "POST", headers: { ...adminHeaders(), "idempotency-key": key() }, body: JSON.stringify({ ...state.context, ...values(event.currentTarget) }) });\n      const slug = byId("publish-form").elements.slug;\n      if (slug.value === "ai-engineer-summit") slug.value = `ai-engineer-summit-${state.program.id.slice(0, 8)}`;\n      show("program-result", state.program); byId("publish-form").querySelector("button").disabled = false;\n    } catch (error) { byId("status").textContent = error.message; }\n  });\n  byId("publish-form").addEventListener("submit", async (event) => {\n    event.preventDefault();\n    try {\n      state.form = await api(`/api/v1/admin/programs/${state.program.id}/forms/publish`, { method: "POST", headers: { ...adminHeaders(), "idempotency-key": key() }, body: JSON.stringify(values(event.currentTarget)) });\n      show("form-result", state.form); byId("submission-form").querySelector("button").disabled = false;\n    } catch (error) {\n      byId("status").textContent = error.status === 409\n        ? "That public slug is already in use. Choose a different slug and publish again."\n        : error.message;\n    }\n  });\n  byId("submission-form").addEventListener("submit", async (event) => {\n    event.preventDefault();\n    try {\n      const submission = await api(`/api/v1/forms/${state.form.slug}/submissions`, { method: "POST", headers: { ...jsonHeaders(), "idempotency-key": key(), "x-public-session-id": crypto.randomUUID() }, body: JSON.stringify(values(event.currentTarget)) });\n      show("submission-result", submission); byId("refresh").disabled = false; await refresh();\n    } catch (error) { byId("status").textContent = error.message; }\n  });\n  async function refresh() {\n    const result = await api(`/api/v1/admin/programs/${state.program.id}/submissions`);\n    const body = byId("submissions"); body.replaceChildren();\n    result.data.forEach((item) => { const row = document.createElement("tr"); [item.speaker_name, item.proposal_title, item.status].forEach((value) => { const cell = document.createElement("td"); cell.textContent = value; row.append(cell); }); body.append(row); });\n  }\n  async function rotateSession() {\n    try {\n      const session = await api("/api/v1/session/refresh", { method: "POST", headers: adminHeaders(), body: "{}" });\n      state.csrfToken = session.csrf_token;\n      byId("status").textContent = "Session rotated; the previous session is revoked.";\n    } catch (error) { byId("status").textContent = error.message; }\n  }\n  async function logout() {\n    try {\n      await api("/api/v1/session/logout", { method: "POST", headers: adminHeaders(), body: "{}" });\n      state.context = null; state.csrfToken = null; state.program = null; state.form = null;\n      byId("status").textContent = "Signed out. The server-side session is revoked.";\n      ["program-form", "publish-form", "submission-form"].forEach((id) => { byId(id).querySelector("button").disabled = true; });\n      byId("refresh").disabled = true; byId("refresh-session").disabled = true; byId("logout").disabled = true;\n      byId("sign-in").textContent = "Sign in as local demo admin";\n    } catch (error) { byId("status").textContent = error.message; }\n  }\n  byId("refresh").addEventListener("click", refresh);\n  byId("refresh-session").addEventListener("click", rotateSession);\n  byId("logout").addEventListener("click", logout);\n  byId("sign-in").addEventListener("click", signIn);\n})();\n'

PRODUCT_CSS = ':root { color-scheme: light; font-family: Inter, ui-sans-serif, system-ui, sans-serif; color: #172033; background: #f4f6fb; }\n* { box-sizing: border-box; }\nbody { margin: 0; }\na { color: #3159d9; }\n.skip-link { position: fixed; top: -5rem; left: 1rem; z-index: 20; padding: .7rem 1rem; background: white; color: #173f9f; }\n.skip-link:focus { top: .5rem; }\n.shell { width: min(72rem, calc(100% - 2rem)); margin: 0 auto; }\nheader { padding: 1.25rem 0; background: #172033; color: white; }\nheader .shell { display: flex; justify-content: space-between; gap: 1rem; align-items: center; }\nheader a { color: white; }\nmain { padding: 2rem 0 4rem; }\n.eyebrow { margin: 0 0 .35rem; color: #64708a; font-size: .8rem; font-weight: 700; letter-spacing: .08em; text-transform: uppercase; }\nh1, h2 { line-height: 1.15; }\nh1 { margin: 0; font-size: clamp(1.8rem, 4vw, 2.8rem); }\n.lede { max-width: 44rem; color: #536079; }\n.grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1.25rem; margin-top: 1.5rem; }\n.card { padding: 1.4rem; border: 1px solid #dce1eb; border-radius: 1rem; background: white; box-shadow: 0 .4rem 1.5rem rgba(27, 39, 70, .06); }\n.card.wide { grid-column: 1 / -1; }\nlabel { display: grid; gap: .4rem; margin: 1rem 0; font-weight: 650; }\ninput, textarea, select { width: 100%; min-height: 2.75rem; padding: .75rem; border: 1px solid #b7c0d1; border-radius: .55rem; background: white; color: inherit; font: inherit; }\nfieldset { margin: 1rem 0; padding: 1rem; border: 1px solid #dce1eb; border-radius: .7rem; }\nfieldset fieldset { padding: .75rem 1rem; }\n.form-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1rem; }\n#evaluators { display: flex; flex-wrap: wrap; gap: .65rem 1.25rem; }\n#evaluators label { display: inline-flex; align-items: center; gap: .5rem; margin: .4rem 0; }\n#evaluators input { width: auto; }\ntextarea { min-height: 8rem; resize: vertical; }\nbutton, .button { min-height: 2.75rem; display: inline-flex; align-items: center; justify-content: center; padding: .72rem 1rem; border: 0; border-radius: .55rem; background: #3159d9; color: white; font: inherit; font-weight: 700; text-decoration: none; cursor: pointer; }\nbutton.secondary, .button.secondary { background: #e8ecf7; color: #253354; }\nbutton:disabled { cursor: not-allowed; opacity: .45; }\n.actions { display: flex; flex-wrap: wrap; gap: .65rem; }\n.status { margin: 1.25rem 0; padding: .8rem 1rem; border-left: .25rem solid #3159d9; background: #eaf0ff; }\n.status.error { border-color: #b42318; background: #fff0ee; }\n:where(a, button, input, textarea, select, summary):focus-visible { outline: 3px solid #e69b00; outline-offset: 3px; }\n[aria-invalid="true"] { border: 2px solid #b42318; }\n.result { overflow-wrap: anywhere; color: #536079; }\n.public-link { display: grid; gap: .6rem; margin-top: 1rem; padding: 1rem; border-radius: .7rem; background: #f1f4fa; }\n.table-scroll { overflow-x: auto; }\ntable { width: 100%; border-collapse: collapse; }\nth, td { padding: .8rem; border-bottom: 1px solid #dce1eb; text-align: left; vertical-align: top; }\nth { color: #536079; font-size: .8rem; text-transform: uppercase; }\n@media (max-width: 48rem) { .grid, .form-grid { grid-template-columns: 1fr; } header .shell { align-items: flex-start; flex-direction: column; } }\n@media (prefers-reduced-motion: reduce) { *, *::before, *::after { scroll-behavior: auto !important; transition: none !important; } }\n'

ADMIN_PROGRAMS_HTML = '<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Programs · SessionBuddy</title><link rel="stylesheet" href="/product/assets/product.css?v=1"><script src="/product/assets/admin-programs.js?v=2" defer></script></head>\n<body><header><div class="shell"><strong>SessionBuddy</strong><a href="/admin/events">Events</a><a href="/engine-room">Operations console</a></div></header><main class="shell"><p class="eyebrow">Program management</p><h1>Call for speakers</h1><p class="lede">Create a program, publish its public proposal form, and review incoming submissions.</p><div id="status" class="status" role="status" aria-live="polite">Checking your session…</div><div class="actions"><button id="sign-in">Sign in</button><a id="manage-access" class="button secondary" href="/admin/programs" hidden>Manage people</a><button id="logout" class="secondary" disabled>Log out</button></div><div class="grid"><section class="card"><h2>Create program</h2><form id="program-form"><label>Program name<input name="name" value="AI Engineer Summit CFP" maxlength="200" required></label><button disabled>Create program</button></form><p id="program-result" class="result">No program created.</p></section><section class="card"><h2>Publish public form</h2><form id="publish-form"><label>Public URL slug<input name="slug" value="ai-engineer-summit" pattern="[a-z0-9-]+" required></label><label>Welcome message<textarea name="welcome_text" required>Share the session you want to bring to our community.</textarea></label><button disabled>Publish form</button></form><div id="publish-result" class="result">Create a program first.</div></section></div></main></body></html>\n'

ADMIN_PROGRAMS_JS = '(() => {\n  "use strict";\n  const coreFields = [\n    { key: "speaker_name", type: "text", label: "Speaker name", required: true, choices: [] },\n    { key: "speaker_email", type: "email", label: "Email", required: true, choices: [] },\n    { key: "proposal_title", type: "text", label: "Proposal title", required: true, choices: [] },\n    { key: "proposal_abstract", type: "textarea", label: "Proposal abstract", required: true, choices: [] }\n  ];\n  const state = { context: null, csrf: null, program: null, fields: structuredClone(coreFields) };\n  const byId = (id) => document.getElementById(id);\n  const json = () => ({ "content-type": "application/json" });\n  const admin = () => ({ ...json(), "x-csrf-token": state.csrf });\n  const key = () => `${crypto.randomUUID()}-${crypto.randomUUID()}`;\n\n  function recordTelemetry(started, response) {\n    const navigation = performance.getEntriesByType("navigation")[0];\n    const width = innerWidth;\n    window.__sessionbuddyTelemetryDraft = {\n      schema_version: 1,\n      page_template: "/admin/programs",\n      navigation_type: navigation?.type || "unknown",\n      device_class: width < 640 ? "mobile" : width < 1024 ? "tablet" : "desktop",\n      sampled: false,\n      lcp_ms: null,\n      inp_ms: null,\n      cls: null,\n      ttfb_ms: navigation?.responseStart ?? null,\n      fcp_ms: null,\n      route_transition_ms: null,\n      critical_api_ms: Math.max(0, performance.now() - started),\n      api_request_id: response.headers.get("x-request-id")\n    };\n  }\n\n  async function api(path, options = {}) {\n    const started = performance.now();\n    const response = await fetch(path, options);\n    recordTelemetry(started, response);\n    const body = response.status === 204 ? null : await response.json();\n    if (!response.ok) {\n      const error = new Error(body?.error?.message || `Request failed (${response.status})`);\n      error.status = response.status;\n      throw error;\n    }\n    return body;\n  }\n\n  function setStatus(message, error = false) {\n    byId("status").textContent = message;\n    byId("status").classList.toggle("error", error);\n  }\n\n  function make(tag, text) {\n    const node = document.createElement(tag);\n    if (text !== undefined) node.textContent = text;\n    return node;\n  }\n\n  function inputLabel(text, input) {\n    const label = make("label", text);\n    label.append(input);\n    return label;\n  }\n\n  function textInput(name, value, required = false) {\n    const input = document.createElement("input");\n    input.name = name;\n    input.value = value || "";\n    input.required = required;\n    input.maxLength = 200;\n    return input;\n  }\n\n  function renderFields() {\n    const list = byId("form-fields");\n    list.replaceChildren();\n    state.fields.forEach((field, index) => {\n      const core = index < coreFields.length;\n      const card = make("fieldset");\n      card.dataset.index = String(index);\n      const legend = make("legend", core ? `Required field: ${field.key}` : `Custom field ${index - 3}`);\n      const keyInput = textInput("field_key", field.key, true);\n      keyInput.pattern = "[a-z][a-z0-9_]*";\n      keyInput.readOnly = core;\n      const type = document.createElement("select");\n      type.name = "field_type";\n      ["text", "textarea", "email", "url", "select"].forEach((value) => type.add(new Option(value, value)));\n      type.value = field.type;\n      if (core) type.disabled = true;\n      const required = document.createElement("input");\n      required.type = "checkbox";\n      required.name = "field_required";\n      required.checked = field.required;\n      required.disabled = core;\n      const choices = textInput("field_choices", (field.choices || []).join(", "));\n      choices.placeholder = "Choice one, Choice two";\n      const conditionSource = textInput("condition_source", field.condition?.source_key || "");\n      conditionSource.placeholder = "format";\n      const conditionValue = textInput("condition_value", field.condition?.value || "");\n      conditionValue.placeholder = "workshop";\n      const operator = document.createElement("select");\n      operator.name = "condition_operator";\n      operator.add(new Option("equals", "equals"));\n      operator.add(new Option("does not equal", "not_equals"));\n      operator.value = field.condition?.operator || "equals";\n      card.append(\n        legend,\n        inputLabel("Field key", keyInput),\n        inputLabel("Label", textInput("field_label", field.label, true)),\n        inputLabel("Type", type),\n        inputLabel("Required", required),\n        inputLabel("Select choices (comma separated)", choices)\n      );\n      if (!core) {\n        card.append(\n          make("p", "Optional display condition"),\n          inputLabel("Show when field key", conditionSource),\n          inputLabel("Comparison", operator),\n          inputLabel("Value", conditionValue)\n        );\n        const remove = make("button", "Remove field");\n        remove.type = "button";\n        remove.className = "secondary";\n        remove.addEventListener("click", () => {\n          readFields();\n          state.fields.splice(index, 1);\n          renderFields();\n        });\n        card.append(remove);\n      }\n      list.append(card);\n    });\n  }\n\n  function readFields() {\n    const fields = [];\n    const conditions = [];\n    byId("form-fields").querySelectorAll("fieldset").forEach((card, index) => {\n      const keyValue = card.elements.field_key.value.trim();\n      const type = card.elements.field_type?.value || coreFields[index].type;\n      const choices = card.elements.field_choices.value.split(",").map((value) => value.trim()).filter(Boolean);\n      const field = {\n        key: keyValue,\n        type,\n        label: card.elements.field_label.value.trim(),\n        required: index < coreFields.length || card.elements.field_required.checked,\n        help_text: "",\n        choices: type === "select" ? choices : []\n      };\n      const source = card.elements.condition_source?.value.trim();\n      const value = card.elements.condition_value?.value.trim();\n      if (source && value) {\n        field.condition = { source_key: source, operator: card.elements.condition_operator.value, value };\n        conditions.push({ ...field.condition, target_key: keyValue });\n      }\n      fields.push(field);\n    });\n    state.fields = fields;\n    return { fields: fields.map(({ condition, ...field }) => field), conditions };\n  }\n\n  function installBuilder() {\n    const publish = byId("publish-form");\n    const submit = publish.querySelector(\'button[type="submit"], button:not([type])\');\n    const heading = make("h3", "Form questions");\n    const help = make("p", "The four identity/proposal fields are required. Add event-specific questions and optional conditions below.");\n    const fields = make("div");\n    fields.id = "form-fields";\n    const add = make("button", "Add question");\n    add.id = "add-field";\n    add.type = "button";\n    add.className = "secondary";\n    add.addEventListener("click", () => {\n      readFields();\n      state.fields.push({ key: `question_${state.fields.length - 3}`, type: "text", label: "New question", required: false, choices: [] });\n      renderFields();\n    });\n    publish.insertBefore(heading, submit);\n    publish.insertBefore(help, submit);\n    publish.insertBefore(fields, submit);\n    publish.insertBefore(add, submit);\n    renderFields();\n  }\n\n  async function restoreSession() {\n    try {\n      const session = await api("/api/v1/auth/session");\n      const requestedEvent = new URLSearchParams(location.search).get("event_id");\n      const eventId = requestedEvent || session.event_id;\n      if (!session.organization_id || !eventId) throw new Error("This account has no active event.");\n      state.context = { organization_id: session.organization_id, event_id: eventId };\n      state.csrf = session.csrf_token;\n      byId("program-form").querySelector("button").disabled = false;\n      byId("logout").disabled = false;\n      byId("manage-access").href = `/admin/events/${encodeURIComponent(eventId)}/access`;\n      byId("manage-access").hidden = false;\n      setStatus("Signed in as organization administrator.");\n    } catch (error) {\n      if (error.status === 401) {\n        location.assign(`/sign-in?redirect=${encodeURIComponent(location.pathname + location.search)}`);\n        return;\n      }\n      setStatus(error.message, true);\n    }\n  }\n\n  byId("sign-in").addEventListener("click", restoreSession);\n  byId("program-form").addEventListener("submit", async (event) => {\n    event.preventDefault();\n    try {\n      const values = Object.fromEntries(new FormData(event.currentTarget));\n      state.program = await api("/api/v1/admin/programs", {\n        method: "POST",\n        headers: { ...admin(), "idempotency-key": key() },\n        body: JSON.stringify({ ...state.context, ...values })\n      });\n      const slug = byId("publish-form").elements.slug;\n      if (slug.value === "ai-engineer-summit") slug.value = `ai-engineer-summit-${state.program.id.slice(0, 8)}`;\n      byId("program-result").textContent = `${state.program.name} · ${state.program.status}`;\n      byId("publish-form").querySelector(\'button[type="submit"], button:not([type])\').disabled = false;\n      setStatus("Program created. Review and publish its public form.");\n    } catch (error) {\n      setStatus(error.message, true);\n    }\n  });\n\n  byId("publish-form").addEventListener("submit", async (event) => {\n    event.preventDefault();\n    try {\n      const values = Object.fromEntries(new FormData(event.currentTarget));\n      const schema = readFields();\n      const form = await api(`/api/v1/admin/programs/${state.program.id}/forms/publish`, {\n        method: "POST",\n        headers: { ...admin(), "idempotency-key": key() },\n        body: JSON.stringify({ slug: values.slug, welcome_text: values.welcome_text, ...schema })\n      });\n      const publicUrl = `${location.origin}/cfp/${form.slug}`;\n      const wrap = byId("publish-result");\n      wrap.replaceChildren();\n      const link = make("a", publicUrl);\n      link.href = publicUrl;\n      const submissions = make("a", "Review submissions");\n      submissions.href = `/admin/programs/${state.program.id}/submissions`;\n      submissions.className = "button secondary";\n      wrap.className = "public-link";\n      wrap.append("Public form is live:", link, submissions);\n      setStatus("Form published successfully.");\n    } catch (error) {\n      setStatus(error.status === 409 ? "That public slug is already in use. Choose another." : error.message, true);\n    }\n  });\n\n  byId("logout").addEventListener("click", async () => {\n    try {\n      await api("/api/v1/session/logout", { method: "POST", headers: admin(), body: "{}" });\n      state.context = null;\n      state.csrf = null;\n      state.program = null;\n      byId("program-form").querySelector("button").disabled = true;\n      byId("publish-form").querySelector(\'button[type="submit"], button:not([type])\').disabled = true;\n      byId("logout").disabled = true;\n      setStatus("Signed out. The server-side session is revoked.");\n    } catch (error) {\n      setStatus(error.message, true);\n    }\n  });\n\n  installBuilder();\n  restoreSession();\n})();\n'

PUBLIC_CFP_HTML = '<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Submit a proposal · SessionBuddy</title><link rel="stylesheet" href="/product/assets/product.css?v=6"><script src="/product/assets/public-cfp.js?v=3" defer></script></head><body><a class="skip-link" href="#main">Skip to form</a><header><div class="shell"><strong>SessionBuddy</strong></div></header><main id="main" class="shell" tabindex="-1"><p class="eyebrow">Call for speakers</p><h1 id="title">Submit a proposal</h1><p id="welcome" class="lede">Loading the published form…</p><div id="status" class="status" role="status" aria-live="polite" tabindex="-1">Loading…</div><section id="sign-in-card" class="card" hidden aria-labelledby="sign-in-title"><h2 id="sign-in-title">Sign in to submit</h2><p>Enter your email address. We will send a one-time sign-in link; no password is needed.</p><form id="sign-in-form"><label>Email address<input name="email" type="email" autocomplete="email" maxlength="320" required></label><button>Send sign-in link</button></form></section><section id="proposal-card" class="card" hidden aria-labelledby="title"><form id="proposal-form"><div id="dynamic-fields"></div><div class="actions"><button id="save-draft" class="secondary" type="button">Save draft</button><button id="submit-proposal" type="submit">Submit proposal</button></div></form><div id="receipt" class="result" role="status" aria-live="polite"></div></section></main></body></html>\n'

PUBLIC_CFP_JS = '(() => {\n  "use strict";\n  const byId = (id) => document.getElementById(id);\n  const slug = decodeURIComponent(location.pathname.split("/").filter(Boolean).pop() || "");\n  const publicSession = crypto.randomUUID();\n  let csrf = "";\n  let draftVersion = 0;\n  let applyFormConditions = () => {};\n  function recordTelemetry(started, response) {\n    const navigation = performance.getEntriesByType("navigation")[0];\n    const width = innerWidth;\n    window.__sessionbuddyTelemetryDraft = { schema_version: 1, page_template: "/cfp/{slug}", navigation_type: navigation?.type || "unknown", device_class: width < 640 ? "mobile" : width < 1024 ? "tablet" : "desktop", sampled: false, lcp_ms: null, inp_ms: null, cls: null, ttfb_ms: navigation?.responseStart ?? null, fcp_ms: null, route_transition_ms: null, critical_api_ms: Math.max(0, performance.now() - started), api_request_id: response.headers.get("x-request-id") };\n  }\n  async function api(path, options = {}) {\n    const started = performance.now();\n    const response = await fetch(path, options);\n    recordTelemetry(started, response);\n    const body = await response.json();\n    if (!response.ok) throw new Error(body.error?.message || `Request failed (${response.status})`);\n    return body;\n  }\n  async function load() {\n    try {\n      const form = await api(`/api/v1/forms/${encodeURIComponent(slug)}`);\n      byId("welcome").textContent = form.welcome_text;\n      renderFields(form.fields || [], form.conditions || []);\n      const sessionResponse = await fetch("/api/v1/auth/session");\n      if (sessionResponse.ok) {\n        const session = await sessionResponse.json();\n        csrf = session.csrf_token;\n        byId("proposal-card").hidden = false;\n        byId("status").textContent = "Signed in. Your draft can be saved on this device or another one.";\n        await loadDraft();\n      } else {\n        byId("sign-in-card").hidden = false;\n        byId("status").textContent = "Sign in with your email address to begin.";\n      }\n    } catch (error) {\n      byId("status").textContent = error.message;\n      byId("status").classList.add("error");\n    }\n  }\n  function renderFields(fields, conditions) {\n    const container = byId("dynamic-fields");\n    container.replaceChildren();\n    for (const field of fields) {\n      const label = document.createElement("label");\n      label.append(document.createTextNode(field.label));\n      let input;\n      if (field.type === "textarea") {\n        input = document.createElement("textarea");\n        input.maxLength = 5000;\n      } else if (field.type === "select") {\n        input = document.createElement("select");\n        const empty = document.createElement("option");\n        empty.value = "";\n        empty.textContent = "Choose…";\n        input.append(empty);\n        for (const choice of field.choices || []) {\n          const option = document.createElement("option");\n          option.value = choice;\n          option.textContent = choice;\n          input.append(option);\n        }\n      } else {\n        input = document.createElement("input");\n        input.type = field.type === "url" || field.type === "email" ? field.type : "text";\n        input.maxLength = 500;\n      }\n      input.name = field.key;\n      input.required = Boolean(field.required);\n      input.dataset.required = field.required ? "true" : "false";\n      if (field.key === "speaker_name") input.autocomplete = "name";\n      if (field.key === "speaker_email") input.autocomplete = "email";\n      label.append(input);\n      if (field.help_text) {\n        const help = document.createElement("span");\n        help.className = "help";\n        help.textContent = field.help_text;\n        label.append(help);\n      }\n      container.append(label);\n    }\n    function applyConditions() {\n      for (const condition of conditions) {\n        const source = byId("proposal-form").elements.namedItem(condition.source_key);\n        const target = byId("proposal-form").elements.namedItem(condition.target_key);\n        if (!source || !target) continue;\n        const matches = String(source.value) === condition.value;\n        const visible = condition.operator === "equals" ? matches : !matches;\n        target.closest("label").hidden = !visible;\n        target.disabled = !visible;\n        target.required = visible && target.dataset.required === "true";\n      }\n    }\n    applyFormConditions = applyConditions;\n    container.addEventListener("input", applyConditions);\n    container.addEventListener("change", applyConditions);\n    applyConditions();\n  }\n  function answers() { return Object.fromEntries(new FormData(byId("proposal-form"))); }\n  async function loadDraft() {\n    const response = await fetch(`/api/v1/forms/${encodeURIComponent(slug)}/draft`);\n    if (!response.ok) return;\n    const draft = await response.json();\n    if (!draft) return;\n    draftVersion = draft.version;\n    for (const [name, value] of Object.entries(draft.answers)) {\n      const field = byId("proposal-form").elements.namedItem(name);\n      if (field) field.value = value;\n    }\n    applyFormConditions();\n    byId("status").textContent = "Your saved draft has been restored.";\n  }\n  byId("sign-in-form").addEventListener("submit", async (event) => {\n    event.preventDefault();\n    const email = new FormData(event.currentTarget).get("email");\n    try {\n      await api("/api/v1/auth/magic-links", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ email, form_slug: slug, redirect_path: location.pathname }) });\n      byId("status").textContent = "Check your email for the one-time sign-in link. It expires in 15 minutes.";\n    } catch (error) { byId("status").textContent = error.message; }\n  });\n  byId("save-draft").addEventListener("click", async () => {\n    try {\n      const draft = await api(`/api/v1/forms/${encodeURIComponent(slug)}/draft`, { method: "PUT", headers: { "content-type": "application/json", "x-csrf-token": csrf }, body: JSON.stringify({ answers: answers(), version: draftVersion }) });\n      draftVersion = draft.version;\n      byId("status").textContent = "Draft saved.";\n    } catch (error) { byId("status").textContent = error.message; }\n  });\n  byId("proposal-form").addEventListener("submit", async (event) => {\n    event.preventDefault();\n    const form = event.currentTarget;\n    const button = byId("submit-proposal");\n    button.disabled = true;\n    button.textContent = "Submitting…";\n    byId("status").classList.remove("error");\n    try {\n      const values = answers();\n      const { speaker_name, speaker_email, proposal_title, proposal_abstract } = values;\n      const submission = await api(`/api/v1/forms/${encodeURIComponent(slug)}/submissions`, { method: "POST", headers: { "content-type": "application/json", "x-csrf-token": csrf, "idempotency-key": `${crypto.randomUUID()}-${crypto.randomUUID()}`, "x-public-session-id": publicSession }, body: JSON.stringify({ speaker_name, speaker_email, proposal_title, proposal_abstract, answers: values }) });\n      byId("status").textContent = "Proposal submitted.";\n      byId("receipt").textContent = `Receipt ${submission.id} · ${submission.status}`;\n      form.querySelectorAll("input, textarea, select, button").forEach((field) => { field.disabled = true; });\n    } catch (error) {\n      byId("status").textContent = error.message;\n      byId("status").classList.add("error");\n      byId("status").focus();\n      button.disabled = false;\n      button.textContent = "Submit proposal";\n    }\n  });\n  load();\n})();\n'

SIGN_IN_HTML = '<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Sign in · SessionBuddy</title><link rel="stylesheet" href="/product/assets/product.css?v=6"><script src="/auth/assets/sign-in.js?v=1" defer></script></head><body><a class="skip-link" href="#main">Skip to sign in</a><header><div class="shell"><strong>SessionBuddy</strong></div></header><main id="main" class="shell" tabindex="-1"><p class="eyebrow">Secure access</p><h1>Sign in</h1><p class="lede">Use the email address your administrator invited. We will send a one-time link—there is no password.</p><div id="status" class="status" role="status" aria-live="polite" tabindex="-1">Enter your email address.</div><section class="card"><form id="sign-in-form"><label>Email address<input name="email" type="email" autocomplete="email" maxlength="320" required></label><button>Send sign-in link</button></form></section></main></body></html>\n'

SIGN_IN_JS = '(() => {\n  "use strict";\n  const form = document.getElementById("sign-in-form");\n  const status = document.getElementById("status");\n  const requested = new URLSearchParams(location.search).get("redirect") || "/";\n  const redirect = requested.startsWith("/") && !requested.startsWith("//") && !requested.includes("\\\\") ? requested : "/";\n  form.addEventListener("submit", async (event) => {\n    event.preventDefault();\n    const button = form.querySelector("button");\n    button.disabled = true;\n    status.textContent = "Sending your sign-in link…";\n    try {\n      const response = await fetch("/api/v1/auth/magic-links", { method: "POST", headers: { "content-type": "application/json" }, body: JSON.stringify({ email: new FormData(form).get("email"), redirect_path: redirect }) });\n      if (!response.ok) throw new Error(`Request failed (${response.status})`);\n      status.textContent = "Check your email. The one-time link expires in 15 minutes.";\n    } catch (error) {\n      status.textContent = error.message;\n      status.focus();\n      button.disabled = false;\n    }\n  });\n})();\n'

ACCESS_ADMIN_HTML = '<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Event access · SessionBuddy</title><link rel="stylesheet" href="/product/assets/product.css?v=6"><script src="/admin/access/assets/access.js?v=1" defer></script></head><body><a class="skip-link" href="#main">Skip to access management</a><header><div class="shell"><strong>SessionBuddy</strong><a href="/admin/programs">Programs</a></div></header><main id="main" class="shell" tabindex="-1"><p class="eyebrow">Event administration</p><h1>People and invitations</h1><p class="lede">Invite administrators, evaluators, and speakers. Access starts only after the recipient verifies their email.</p><div id="status" class="status" role="status" aria-live="polite" tabindex="-1">Checking your session…</div><section class="card"><h2>Send invitation</h2><form id="invite-form"><label>Email address<input name="email" type="email" autocomplete="email" maxlength="320" required></label><label>Event role<select name="role"><option value="speaker">Speaker</option><option value="evaluator">Evaluator</option><option value="event_admin">Event administrator</option></select></label><label>Expires after<select name="expires_in_days"><option value="7">7 days</option><option value="14" selected>14 days</option><option value="30">30 days</option></select></label><button>Invite</button></form></section><section class="card"><h2>Pending and past invitations</h2><ul id="invitation-list" class="result"><li>Loading…</li></ul></section><section class="card"><h2>Event members</h2><ul id="member-list" class="result"><li>Loading…</li></ul></section></main></body></html>\n'

ACCESS_ADMIN_JS = '(() => {\n  "use strict";\n  const match = location.pathname.match(/^\\/admin\\/events\\/([^/]+)\\/access$/);\n  const eventId = match ? decodeURIComponent(match[1]) : "";\n  const byId = (id) => document.getElementById(id);\n  let csrf = "";\n  async function api(path, options = {}) {\n    const response = await fetch(path, { credentials: "same-origin", ...options });\n    const body = response.status === 204 ? null : await response.json();\n    if (!response.ok) { const error = new Error(body?.error?.message || `Request failed (${response.status})`); error.status = response.status; throw error; }\n    return body;\n  }\n  function item(text) { const node = document.createElement("li"); node.textContent = text; return node; }\n  async function load() {\n    const session = await api("/api/v1/auth/session");\n    csrf = session.csrf_token;\n    const [invitations, members] = await Promise.all([\n      api(`/api/v1/admin/events/${encodeURIComponent(eventId)}/invitations`),\n      api(`/api/v1/admin/events/${encodeURIComponent(eventId)}/members`)\n    ]);\n    const invitationList = byId("invitation-list"); invitationList.replaceChildren();\n    for (const invitation of invitations.data) {\n      const node = item(`${invitation.email} · ${invitation.role.replaceAll("_", " ")} · ${invitation.status}`);\n      if (invitation.status === "pending") {\n        const button = document.createElement("button"); button.className = "secondary"; button.textContent = "Revoke";\n        button.addEventListener("click", async () => { await api(`/api/v1/admin/events/${encodeURIComponent(eventId)}/invitations/${encodeURIComponent(invitation.id)}`, { method: "DELETE", headers: { "content-type": "application/json", "x-csrf-token": csrf } }); await load(); });\n        node.append(" ", button);\n      }\n      invitationList.append(node);\n    }\n    if (!invitations.data.length) invitationList.append(item("No invitations yet."));\n    const memberList = byId("member-list"); memberList.replaceChildren();\n    for (const member of members.data) {\n      const node = item(`${member.email} · ${member.role.replaceAll("_", " ")} · ${member.status}`);\n      if (member.status === "active" && member.user_id !== session.user_id) {\n        const button = document.createElement("button"); button.className = "secondary"; button.textContent = "Revoke role";\n        button.addEventListener("click", async () => { await api(`/api/v1/admin/events/${encodeURIComponent(eventId)}/members/${encodeURIComponent(member.user_id)}/roles/${encodeURIComponent(member.role)}`, { method: "DELETE", headers: { "content-type": "application/json", "x-csrf-token": csrf } }); await load(); });\n        node.append(" ", button);\n      }\n      memberList.append(node);\n    }\n    byId("status").textContent = "Event access is up to date.";\n  }\n  byId("invite-form").addEventListener("submit", async (event) => {\n    event.preventDefault();\n    const form = event.currentTarget;\n    const values = Object.fromEntries(new FormData(form));\n    try {\n      await api(`/api/v1/admin/events/${encodeURIComponent(eventId)}/invitations`, { method: "POST", headers: { "content-type": "application/json", "x-csrf-token": csrf }, body: JSON.stringify({ ...values, expires_in_days: Number(values.expires_in_days) }) });\n      form.reset(); byId("status").textContent = "Invitation created and queued for delivery."; await load();\n    } catch (error) { byId("status").textContent = error.message; byId("status").focus(); }\n  });\n  if (!eventId) { byId("status").textContent = "This event link is invalid."; return; }\n  load().catch((error) => { if (error.status === 401) location.assign(`/sign-in?redirect=${encodeURIComponent(location.pathname)}`); else byId("status").textContent = error.message; });\n})();\n'

EVENTS_ADMIN_HTML = '<!doctype html>\n<html lang="en">\n<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <title>Events · SessionBuddy</title>\n  <link rel="stylesheet" href="/product/assets/product.css?v=6">\n  <script src="/admin/events/assets/events.js?v=2" defer></script>\n</head>\n<body>\n  <a class="skip-link" href="#main">Skip to event management</a>\n  <header><div class="shell"><strong>SessionBuddy</strong><a href="/admin/programs">Programs</a></div></header>\n  <main id="main" class="shell" tabindex="-1">\n    <p class="eyebrow">Organization administration</p>\n    <h1>Events</h1>\n    <p class="lede">Create events and manage their people, submissions, agenda, and onboarding.</p>\n    <div id="status" class="status" role="status" aria-live="polite" tabindex="-1">Checking your session…</div>\n\n    <section class="card">\n      <h2>Organization</h2>\n      <form id="organization-form">\n        <label>Organization<select name="organization_id" id="organization" required></select></label>\n        <label>Name<input name="name" maxlength="200" required></label>\n        <input name="version" type="hidden">\n        <button>Update organization</button>\n      </form>\n    </section>\n\n    <section class="card">\n      <h2 id="event-form-heading">Create an event</h2>\n      <form id="event-form">\n        <input name="event_id" type="hidden">\n        <input name="version" type="hidden">\n        <label>Event name<input name="name" maxlength="200" required></label>\n        <label>Starts<input name="starts_at" type="datetime-local" required></label>\n        <label>Ends<input name="ends_at" type="datetime-local" required></label>\n        <label>Time zone<input name="time_zone" value="Asia/Kolkata" maxlength="100" required></label>\n        <label>Delivery<select name="delivery_mode"><option value="in_person">In person</option><option value="virtual">Virtual</option><option value="hybrid" selected>Hybrid</option></select></label>\n        <label>Location<input name="location" maxlength="500"></label>\n        <label>Description<textarea name="description" maxlength="5000"></textarea></label>\n        <label id="event-status-label" hidden>Status<select name="status"><option value="draft">Draft</option><option value="active">Active</option><option value="archived">Archived</option></select></label>\n        <button id="save-event">Create event</button>\n        <button id="cancel-event-edit" type="button" class="secondary" hidden>Cancel edit</button>\n      </form>\n    </section>\n\n    <section class="card">\n      <h2>Existing events</h2>\n      <ul id="event-list" class="result"><li>Loading…</li></ul>\n    </section>\n  </main>\n</body>\n</html>\n'

EVENTS_ADMIN_JS = '(() => {\n  "use strict";\n\n  const byId = (id) => document.getElementById(id);\n  const state = { csrf: "", organizationId: "", organizations: new Map(), events: new Map() };\n\n  async function api(path, options = {}) {\n    const response = await fetch(path, { credentials: "same-origin", ...options });\n    const body = response.status === 204 ? null : await response.json();\n    if (!response.ok) {\n      const error = new Error(body?.error?.message || `Request failed (${response.status})`);\n      error.status = response.status;\n      throw error;\n    }\n    return body;\n  }\n\n  function setStatus(message, error = false) {\n    const status = byId("status");\n    status.textContent = message;\n    status.classList.toggle("error", error);\n    if (error) status.focus();\n  }\n\n  function button(label, handler) {\n    const control = document.createElement("button");\n    control.type = "button";\n    control.className = "secondary";\n    control.textContent = label;\n    control.addEventListener("click", handler);\n    return control;\n  }\n\n  function link(label, href) {\n    const control = document.createElement("a");\n    control.textContent = label;\n    control.href = href;\n    control.className = "button secondary";\n    return control;\n  }\n\n  function localDateTime(timestamp) {\n    const date = new Date(timestamp);\n    const local = new Date(timestamp - date.getTimezoneOffset() * 60_000);\n    return local.toISOString().slice(0, 16);\n  }\n\n  function resetEventForm() {\n    const form = byId("event-form");\n    form.reset();\n    form.elements.event_id.value = "";\n    form.elements.version.value = "";\n    form.elements.time_zone.value = Intl.DateTimeFormat().resolvedOptions().timeZone || "UTC";\n    byId("event-form-heading").textContent = "Create an event";\n    byId("save-event").textContent = "Create event";\n    byId("event-status-label").hidden = true;\n    byId("cancel-event-edit").hidden = true;\n  }\n\n  function editEvent(event) {\n    const form = byId("event-form");\n    form.elements.event_id.value = event.id;\n    form.elements.version.value = String(event.version);\n    form.elements.name.value = event.name;\n    form.elements.starts_at.value = localDateTime(event.starts_at_ms);\n    form.elements.ends_at.value = localDateTime(event.ends_at_ms);\n    form.elements.time_zone.value = event.time_zone;\n    form.elements.delivery_mode.value = event.delivery_mode;\n    form.elements.location.value = event.location || "";\n    form.elements.description.value = event.description || "";\n    form.elements.status.value = event.status;\n    byId("event-form-heading").textContent = `Edit ${event.name}`;\n    byId("save-event").textContent = "Update event";\n    byId("event-status-label").hidden = false;\n    byId("cancel-event-edit").hidden = false;\n    form.scrollIntoView({ behavior: "smooth", block: "start" });\n    form.elements.name.focus();\n  }\n\n  function eventItem(event) {\n    const item = document.createElement("li");\n    const heading = document.createElement("strong");\n    heading.textContent = event.name;\n    const details = document.createElement("span");\n    details.textContent = ` · ${event.status} · ${new Date(event.starts_at_ms).toLocaleString()}`;\n    item.append(\n      heading,\n      details,\n      " ",\n      link("Programs", `/admin/programs?event_id=${encodeURIComponent(event.id)}`),\n      " ",\n      link("People", `/admin/events/${encodeURIComponent(event.id)}/access`),\n      " ",\n      link("Onboarding", `/admin/events/${encodeURIComponent(event.id)}/onboarding`),\n      " ",\n      link("Agenda", `/admin/events/${encodeURIComponent(event.id)}/agenda`),\n      " ",\n      link("Public schedule", `/events/${encodeURIComponent(event.id)}/schedule`),\n      " ",\n      button("Edit", () => editEvent(event))\n    );\n    return item;\n  }\n\n  function showOrganization() {\n    const organization = state.organizations.get(state.organizationId);\n    const form = byId("organization-form");\n    form.elements.name.value = organization?.name || "";\n    form.elements.version.value = organization ? String(organization.version) : "";\n  }\n\n  async function loadEvents(organizationId) {\n    state.organizationId = organizationId;\n    showOrganization();\n    resetEventForm();\n    const result = await api(`/api/v1/admin/organizations/${encodeURIComponent(organizationId)}/events`);\n    state.events = new Map(result.data.map((event) => [event.id, event]));\n    const list = byId("event-list");\n    list.replaceChildren();\n    for (const event of result.data) list.append(eventItem(event));\n    if (!result.data.length) {\n      const empty = document.createElement("li");\n      empty.textContent = "No events yet.";\n      list.append(empty);\n    }\n  }\n\n  async function initialize() {\n    const session = await api("/api/v1/auth/session");\n    state.csrf = session.csrf_token;\n    const result = await api("/api/v1/admin/organizations");\n    state.organizations = new Map(result.data.map((organization) => [organization.id, organization]));\n    const select = byId("organization");\n    select.replaceChildren();\n    for (const organization of result.data) select.add(new Option(organization.name, organization.id));\n    if (!result.data.length) throw new Error("This account does not administer an organization.");\n    if (session.organization_id && state.organizations.has(session.organization_id)) {\n      select.value = session.organization_id;\n    }\n    await loadEvents(select.value);\n    setStatus("Events are up to date.");\n  }\n\n  byId("organization").addEventListener("change", (event) => {\n    loadEvents(event.currentTarget.value)\n      .then(() => setStatus("Organization selected."))\n      .catch((error) => setStatus(error.message, true));\n  });\n\n  byId("organization-form").addEventListener("submit", async (event) => {\n    event.preventDefault();\n    const values = Object.fromEntries(new FormData(event.currentTarget));\n    try {\n      const organization = await api(\n        `/api/v1/admin/organizations/${encodeURIComponent(values.organization_id)}`,\n        {\n          method: "PATCH",\n          headers: { "content-type": "application/json", "x-csrf-token": state.csrf },\n          body: JSON.stringify({ name: values.name, version: Number(values.version) })\n        }\n      );\n      state.organizations.set(organization.id, organization);\n      byId("organization").selectedOptions[0].textContent = organization.name;\n      showOrganization();\n      setStatus("Organization updated.");\n    } catch (error) {\n      setStatus(error.status === 409 ? "The organization changed elsewhere. Reload and try again." : error.message, true);\n    }\n  });\n\n  byId("event-form").addEventListener("submit", async (event) => {\n    event.preventDefault();\n    const values = Object.fromEntries(new FormData(event.currentTarget));\n    const eventId = values.event_id;\n    const body = {\n      name: values.name,\n      starts_at_ms: new Date(values.starts_at).getTime(),\n      ends_at_ms: new Date(values.ends_at).getTime(),\n      time_zone: values.time_zone,\n      delivery_mode: values.delivery_mode,\n      location: values.location || null,\n      description: values.description || null\n    };\n    if (eventId) {\n      body.version = Number(values.version);\n      body.status = values.status;\n    }\n    try {\n      await api(\n        eventId\n          ? `/api/v1/admin/events/${encodeURIComponent(eventId)}`\n          : `/api/v1/admin/organizations/${encodeURIComponent(state.organizationId)}/events`,\n        {\n          method: eventId ? "PATCH" : "POST",\n          headers: { "content-type": "application/json", "x-csrf-token": state.csrf },\n          body: JSON.stringify(body)\n        }\n      );\n      setStatus(eventId ? "Event updated." : "Event created.");\n      await loadEvents(state.organizationId);\n    } catch (error) {\n      setStatus(error.status === 409 ? "The event changed elsewhere. Reload and try again." : error.message, true);\n    }\n  });\n\n  byId("cancel-event-edit").addEventListener("click", resetEventForm);\n\n  initialize().catch((error) => {\n    if (error.status === 401) {\n      location.assign(`/sign-in?redirect=${encodeURIComponent(location.pathname)}`);\n    } else {\n      setStatus(error.message, true);\n    }\n  });\n})();\n'

ADMIN_SUBMISSIONS_HTML = '<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Submissions · SessionBuddy</title><link rel="stylesheet" href="/product/assets/product.css?v=4"><script src="/product/assets/admin-submissions.js?v=4" defer></script></head><body><header><div class="shell"><strong>SessionBuddy</strong><a href="/admin/programs">Programs</a></div></header><main class="shell"><p class="eyebrow">Program management</p><h1>Submissions</h1><div id="status" class="status" role="status" aria-live="polite">Checking your session…</div><section class="card"><p>Select the submissions to include in the next round.</p><div class="table-scroll"><table><thead><tr><th>Include</th><th>Speaker</th><th>Proposal</th><th>Abstract</th><th>Status</th></tr></thead><tbody id="submissions"><tr><td colspan="5">Loading…</td></tr></tbody></table></div></section><section class="card"><p class="eyebrow">Evaluation</p><h2>Configure evaluation round</h2><form id="round-form"><fieldset id="round-fields"><label>Round name<input name="name" value="Initial review" required maxlength="200"></label><div class="form-grid"><label>Minimum rating<input name="rating_min" type="number" value="1" min="0" max="9" required></label><label>Maximum rating<input name="rating_max" type="number" value="5" min="1" max="10" required></label></div><label>Recommendations<input name="recommendations" value="strong_accept, accept, reject, strong_reject" required><small>Comma-separated, with at least two unique choices.</small></label><label>Evaluator guidance<textarea name="evaluator_guidance" rows="3">Score the proposal itself. Do not include speaker identity or reputation in the rating.</textarea></label><label>Assignment strategy<select name="assignment_strategy"><option value="balanced">Balanced — distribute submissions evenly</option><option value="all">All — every evaluator reviews every submission</option></select></label><fieldset><legend>Evaluators</legend><div id="evaluators">Loading evaluators…</div></fieldset><button id="open-round" disabled>Open evaluation round</button></fieldset></form><a class="button secondary" href="/reviews">Go to review workspace</a><div id="round-result" class="public-link"></div></section></main></body></html>\n'

ADMIN_SUBMISSIONS_JS = '(() => {\n  "use strict";\n  const byId = (id) => document.getElementById(id);\n  const main = document.querySelector("main");\n  main.id = "main";\n  main.tabIndex = -1;\n  const skip = document.createElement("a");\n  skip.className = "skip-link";\n  skip.href = "#main";\n  skip.textContent = "Skip to content";\n  document.body.prepend(skip);\n  document.querySelectorAll("th").forEach((heading) => heading.setAttribute("scope", "col"));\n  byId("status").tabIndex = -1;\n  const parts = location.pathname.split("/").filter(Boolean);\n  const programId = parts[2] || "";\n  const state = { csrf: "", userId: "", submissions: [], evaluators: [] };\n  function showRound(round) {\n    const link = document.createElement("a");\n    link.href = `/admin/evaluation-rounds/${round.id}`;\n    link.textContent = "Monitor round and record decisions";\n    byId("round-result").replaceChildren(link);\n    byId("open-round").disabled = true;\n    byId("round-fields").disabled = true;\n  }\n  function recordTelemetry(started, response) {\n    const navigation = performance.getEntriesByType("navigation")[0];\n    const width = innerWidth;\n    window.__sessionbuddyTelemetryDraft = { schema_version: 1, page_template: "/admin/programs/{program_id}/submissions", navigation_type: navigation?.type || "unknown", device_class: width < 640 ? "mobile" : width < 1024 ? "tablet" : "desktop", sampled: false, lcp_ms: null, inp_ms: null, cls: null, ttfb_ms: navigation?.responseStart ?? null, fcp_ms: null, route_transition_ms: null, critical_api_ms: Math.max(0, performance.now() - started), api_request_id: response.headers.get("x-request-id") };\n  }\n  async function api(path, options = {}) {\n    const started = performance.now();\n    const response = await fetch(path, options);\n    recordTelemetry(started, response);\n    const body = await response.json();\n    if (!response.ok) throw new Error(body.error?.message || `Request failed (${response.status})`);\n    return body;\n  }\n  async function load() {\n    try {\n      const session = await api("/api/v1/auth/session");\n      state.csrf = session.csrf_token;\n      state.userId = session.user_id;\n      const result = await api(`/api/v1/admin/programs/${encodeURIComponent(programId)}/submissions`);\n      state.submissions = result.data;\n      const evaluatorResult = await api(`/api/v1/admin/programs/${encodeURIComponent(programId)}/evaluators`);\n      state.evaluators = evaluatorResult.data;\n      const evaluatorChoices = byId("evaluators");\n      evaluatorChoices.replaceChildren();\n      state.evaluators.forEach((evaluator) => {\n        const label = document.createElement("label");\n        const input = document.createElement("input");\n        input.type = "checkbox";\n        input.name = "evaluator_user_ids";\n        input.value = evaluator.user_id;\n        input.checked = true;\n        label.append(input, evaluator.display_name);\n        evaluatorChoices.append(label);\n      });\n      const body = byId("submissions");\n      body.replaceChildren();\n      if (!result.data.length) {\n        const row = document.createElement("tr");\n        const cell = document.createElement("td");\n        cell.colSpan = 5;\n        cell.textContent = "No submissions yet.";\n        row.append(cell);\n        body.append(row);\n      }\n      result.data.forEach((item) => {\n        const row = document.createElement("tr");\n        const selectionCell = document.createElement("td");\n        const selection = document.createElement("input");\n        selection.type = "checkbox";\n        selection.name = "submission_ids";\n        selection.value = item.id;\n        selection.checked = true;\n        selection.setAttribute("aria-label", `Include ${item.proposal_title}`);\n        selectionCell.append(selection);\n        row.append(selectionCell);\n        [item.speaker_name, item.proposal_title, item.proposal_abstract, item.status].forEach((value) => {\n          const cell = document.createElement("td");\n          cell.textContent = value;\n          row.append(cell);\n        });\n        body.append(row);\n      });\n      byId("status").textContent = `${result.data.length} submission${result.data.length === 1 ? "" : "s"}.`;\n      byId("open-round").disabled = !result.data.length || !state.evaluators.length;\n      const currentRound = await api(`/api/v1/admin/programs/${encodeURIComponent(programId)}/evaluation-rounds/current`);\n      if (currentRound) showRound(currentRound);\n    } catch (error) {\n      byId("status").textContent = `${error.message}. Return to Programs and sign in.`;\n      byId("status").classList.add("error");\n    }\n  }\n  byId("round-form").addEventListener("submit", async (event) => {\n    event.preventDefault();\n    const button = byId("open-round");\n    button.disabled = true;\n    try {\n      const values = new FormData(event.currentTarget);\n      const recommendations = String(values.get("recommendations") || "").split(",").map((choice) => choice.trim()).filter(Boolean);\n      const round = await api(`/api/v1/admin/programs/${encodeURIComponent(programId)}/evaluation-rounds`, {\n        method: "POST",\n        headers: { "content-type": "application/json", "x-csrf-token": state.csrf, "idempotency-key": `${crypto.randomUUID()}-${crypto.randomUUID()}` },\n        body: JSON.stringify({ name: values.get("name"), rating_min: Number(values.get("rating_min")), rating_max: Number(values.get("rating_max")), recommendations, evaluator_guidance: values.get("evaluator_guidance"), assignment_strategy: values.get("assignment_strategy"), submission_ids: [...document.querySelectorAll(\'input[name="submission_ids"]:checked\')].map((input) => input.value), evaluator_user_ids: values.getAll("evaluator_user_ids") })\n      });\n      byId("status").textContent = `${round.name} opened with ${round.assignment_count} assignments across ${round.evaluator_count} evaluators.`;\n      showRound(round);\n    } catch (error) {\n      byId("status").textContent = error.message;\n      byId("status").classList.add("error");\n      button.disabled = false;\n    }\n  });\n  load();\n})();\n'

REVIEWS_HTML = '<!doctype html>\n<html lang="en"><head><meta charset="UTF-8" /><meta name="viewport" content="width=device-width, initial-scale=1.0" /><meta name="color-scheme" content="light" /><title>SessionBuddy · Reviews</title>  <script type="module" crossorigin src="/app/assets/reviews.js"></script>\n  <link rel="stylesheet" crossorigin href="/app/assets/reviews.css">\n</head><body><a class="review-skip" href="#root">Skip to review workspace</a><div id="root" tabindex="-1"></div><style>.review-skip{position:fixed;top:-5rem;left:1rem;z-index:20;padding:.7rem 1rem;background:white;color:#173f9f}.review-skip:focus{top:.5rem}:where(a,button,input,select,textarea,summary):focus-visible{outline:3px solid #e69b00;outline-offset:3px}@media(prefers-reduced-motion:reduce){*,:before,:after{scroll-behavior:auto!important;transition:none!important}}</style></body></html>\n'

REVIEWS_CSS = ':root{font-family:Inter,ui-sans-serif,system-ui,sans-serif;color:#17201d;background:#f4f7f5;font-synthesis:none}*{box-sizing:border-box}body{margin:0}header{display:flex;justify-content:space-between;padding:1rem clamp(1rem,4vw,4rem);background:#112c24;color:#fff}header a{color:#fff;font-weight:800;text-decoration:none}main{max-width:78rem;margin:auto;padding:clamp(1.5rem,4vw,4rem)}.hero{max-width:48rem}.eyebrow,.meta{color:#27745b;font-weight:750;text-transform:uppercase;letter-spacing:.08em;font-size:.78rem}h1{font-size:clamp(2.25rem,6vw,4.5rem);line-height:.98;margin:.4rem 0 1rem;letter-spacing:-.05em}.toolbar{margin:2rem 0;padding:1rem 1.25rem;display:flex;gap:1rem;justify-content:space-between;align-items:center;background:#fff;border:1px solid #dce5e1;border-radius:1rem}.toolbar p{margin:0}.grid,.metrics{display:grid;gap:1.25rem;grid-template-columns:repeat(auto-fit,minmax(min(100%,18rem),1fr))}.metrics{margin-bottom:1.25rem}.metrics article{display:grid;gap:.35rem}.metrics strong{font-size:2rem}article{background:#fff;border:1px solid #dce5e1;border-radius:1.25rem;padding:1.5rem;box-shadow:0 1rem 3rem #112c240f}.meta{display:flex;justify-content:space-between;gap:1rem}h2{margin-bottom:.25rem}.speaker,.help{color:#5e6c67}.speaker{margin-top:0}.help{font-size:.875rem}aside,.confirmation{margin:1rem 0;padding:1rem;border-radius:.75rem;background:#edf5f1}.confirmation{border:1px solid #ef6c3e;background:#fff3ee}details{margin-top:1.25rem;padding-top:1rem;border-top:1px solid #dce5e1}summary{cursor:pointer;font-weight:750}label{display:grid;gap:.4rem;margin-top:1rem;font-weight:700}input,select,textarea{width:100%;border:1px solid #aebdb7;border-radius:.65rem;padding:.75rem;font:inherit;background:#fff}button{border:0;border-radius:999px;padding:.75rem 1rem;background:#ef6c3e;color:#20130e;font:inherit;font-weight:800;cursor:pointer}button.secondary{background:#e2ebe7}button:disabled{cursor:not-allowed;opacity:.5}.actions{display:flex;justify-content:flex-end;gap:.7rem;margin-top:1.25rem}@media(max-width:40rem){.toolbar{align-items:stretch;flex-direction:column}.toolbar button{width:100%}}\n'

