SPEAKER_PORTAL_HTML = '<!doctype html>\n<html lang="en">\n<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <meta name="color-scheme" content="light">\n  <title>Speaker portal · SessionBuddy</title>\n  <link rel="stylesheet" href="/speaker/assets/speaker.css?v=1">\n  <script src="/speaker/assets/speaker-portal.js?v=1" defer></script>\n</head>\n<body>\n  <a class="skip-link" href="#main">Skip to content</a>\n  <header class="site-header">\n    <div class="shell header-layout">\n      <a class="brand" href="/speaker" aria-label="SessionBuddy speaker portal home">SessionBuddy</a>\n      <nav aria-label="Speaker portal">\n        <a href="#overview" aria-current="page">Home</a>\n        <a href="#tasks">Tasks</a>\n        <a href="#submissions">Submissions</a>\n        <a href="#profile">Profile</a>\n        <a href="#assets">Assets</a>\n      </nav>\n    </div>\n  </header>\n\n  <main id="main" class="shell" tabindex="-1">\n    <div id="status" class="status" role="status" aria-live="polite">\n      Loading your speaker portal…\n    </div>\n\n    <section id="auth-state" class="state-panel" hidden aria-labelledby="auth-title">\n      <p class="eyebrow">Speaker access required</p>\n      <h1 id="auth-title">Open your speaker portal</h1>\n      <p>In production, use the secure link in your email. For this local review, start the isolated speaker demo.</p>\n      <button id="start-demo" type="button">Sign in</button>\n    </section>\n\n    <div id="portal" hidden>\n      <section id="overview" class="hero" aria-labelledby="portal-title">\n        <div>\n          <p class="eyebrow">Speaker portal</p>\n          <h1 id="portal-title">Welcome</h1>\n          <p id="event-summary" class="lede"></p>\n          <p id="event-timezone" class="timezone"></p>\n        </div>\n        <div class="progress-card">\n          <span id="progress-label">Onboarding progress</span>\n          <strong id="progress-count">0 of 0 complete</strong>\n          <progress id="progress" value="0" max="1" aria-labelledby="progress-label progress-count"></progress>\n          <p id="next-deadline">No upcoming deadline.</p>\n        </div>\n      </section>\n\n      <div class="portal-grid">\n        <section id="tasks" class="panel" aria-labelledby="tasks-title">\n          <div class="section-heading">\n            <div><p class="eyebrow">What’s next</p><h2 id="tasks-title">Outstanding tasks</h2></div>\n            <span id="task-count" class="count-badge">0</span>\n          </div>\n          <ul id="task-list" class="item-list" aria-describedby="task-help"></ul>\n          <p id="task-help" class="help">Completing the destination action completes its task automatically.</p>\n        </section>\n\n        <section id="submissions" class="panel" aria-labelledby="submissions-title">\n          <div class="section-heading">\n            <div><p class="eyebrow">Your proposals</p><h2 id="submissions-title">Submissions</h2></div>\n          </div>\n          <ul id="submission-list" class="item-list"></ul>\n        </section>\n\n        <section id="profile" class="panel profile-panel" aria-labelledby="profile-title">\n          <p class="eyebrow">Shared speaker details</p>\n          <h2 id="profile-title">Profile</h2>\n          <p class="help">Required fields are marked “required.” Changes apply to your shared speaker profile, not past proposal answers.</p>\n          <div id="error-summary" class="error-summary" role="alert" tabindex="-1" hidden>\n            <h3>Check your profile</h3><ul></ul>\n          </div>\n          <form id="profile-form" novalidate>\n            <div class="form-grid">\n              <label for="display-name">Name <span>required</span></label>\n              <div><input id="display-name" name="display_name" autocomplete="name" maxlength="200" required aria-describedby="display-name-error"><p id="display-name-error" class="field-error"></p></div>\n              <label for="job-title">Job title</label>\n              <div><input id="job-title" name="job_title" autocomplete="organization-title" maxlength="200" aria-describedby="job-title-error"><p id="job-title-error" class="field-error"></p></div>\n              <label for="company">Company</label>\n              <div><input id="company" name="company" autocomplete="organization" maxlength="200" aria-describedby="company-error"><p id="company-error" class="field-error"></p></div>\n              <label for="location">Location</label>\n              <div><input id="location" name="location" autocomplete="address-level2" maxlength="200" aria-describedby="location-error"><p id="location-error" class="field-error"></p></div>\n              <label for="website">Website</label>\n              <div><input id="website" name="website" type="url" inputmode="url" autocomplete="url" placeholder="https://example.com" maxlength="500" aria-describedby="website-error"><p id="website-error" class="field-error"></p></div>\n              <label for="biography">Biography <span>required</span></label>\n              <div><textarea id="biography" name="biography" rows="7" maxlength="5000" required aria-describedby="biography-help biography-count biography-error"></textarea><div class="field-meta"><p id="biography-help" class="help">Write a short introduction for event materials.</p><p id="biography-count" class="help">0 of 5,000 characters</p></div><p id="biography-error" class="field-error"></p></div>\n            </div>\n            <div id="stale-warning" class="stale-warning" role="alert" tabindex="-1" hidden>\n              <strong>Your profile changed elsewhere.</strong>\n              <p>Reload the latest version before saving again. Copy any unsaved text first.</p>\n              <button id="reload-profile" class="secondary" type="button">Reload latest profile</button>\n            </div>\n            <div class="actions"><button id="save-profile" type="submit">Save profile</button></div>\n          </form>\n        </section>\n\n        <section id="assets" class="panel profile-panel" aria-labelledby="assets-title">\n          <p class="eyebrow">Private uploads</p>\n          <h2 id="assets-title">Assets</h2>\n          <p class="help">Files stay private while they are checked. Only the latest clean version becomes current.</p>\n          <div id="asset-status" class="inline-status" role="status" aria-live="polite">Loading current assets…</div>\n          <ul id="asset-list" class="asset-list"><li>Loading…</li></ul>\n          <div class="upload-grid">\n            <form class="upload-card" data-kind="headshot">\n              <h3>Headshot</h3><p>JPEG, PNG, or WebP · up to 5 MB</p>\n              <label for="headshot-file">Choose headshot</label>\n              <input id="headshot-file" name="file" type="file" accept="image/jpeg,image/png,image/webp" required>\n              <button type="submit">Upload headshot</button>\n              <progress max="100" value="0" hidden aria-label="Headshot upload progress"></progress>\n              <p class="upload-status" role="status"></p>\n            </form>\n            <form class="upload-card" data-kind="slides">\n              <h3>Slides</h3><p>PDF, PowerPoint, or OpenDocument · up to 50 MB</p>\n              <label for="slides-submission">Session</label><select id="slides-submission" name="submission_id" required><option value="">Choose a session</option></select>\n              <label for="slides-file">Choose slides</label>\n              <input id="slides-file" name="file" type="file" accept="application/pdf,application/vnd.ms-powerpoint,application/vnd.openxmlformats-officedocument.presentationml.presentation,application/vnd.oasis.opendocument.presentation" required>\n              <button type="submit">Upload slides</button>\n              <progress max="100" value="0" hidden aria-label="Slides upload progress"></progress>\n              <p class="upload-status" role="status"></p>\n            </form>\n            <form class="upload-card" data-kind="supporting_document">\n              <h3>Supporting document</h3><p>PDF · up to 20 MB</p>\n              <label for="document-submission">Session</label><select id="document-submission" name="submission_id" required><option value="">Choose a session</option></select>\n              <label for="document-file">Choose document</label>\n              <input id="document-file" name="file" type="file" accept="application/pdf" required>\n              <button type="submit">Upload document</button>\n              <progress max="100" value="0" hidden aria-label="Document upload progress"></progress>\n              <p class="upload-status" role="status"></p>\n            </form>\n          </div>\n        </section>\n      </div>\n    </div>\n  </main>\n</body>\n</html>\n'

SPEAKER_PORTAL_JS = '(() => {\n  "use strict";\n  const state = { csrf: "", portal: null, version: null };\n  const uploadRules = {\n    headshot: { max: 5 * 1024 * 1024, types: new Set(["image/jpeg", "image/png", "image/webp"]) },\n    slides: { max: 50 * 1024 * 1024, types: new Set(["application/pdf", "application/vnd.ms-powerpoint", "application/vnd.openxmlformats-officedocument.presentationml.presentation", "application/vnd.oasis.opendocument.presentation"]) },\n    supporting_document: { max: 20 * 1024 * 1024, types: new Set(["application/pdf"]) }\n  };\n  const byId = (id) => document.getElementById(id);\n  const make = (tag, text, className) => {\n    const node = document.createElement(tag);\n    if (text !== undefined) node.textContent = text;\n    if (className) node.className = className;\n    return node;\n  };\n\n  function setStatus(message, kind = "") {\n    const status = byId("status");\n    status.textContent = message;\n    status.className = `status${kind ? ` ${kind}` : ""}`;\n  }\n\n  function recordTelemetry(started, response) {\n    const navigation = performance.getEntriesByType("navigation")[0];\n    const width = innerWidth;\n    window.__sessionbuddyTelemetryDraft = {\n      schema_version: 1, page_template: "/speaker",\n      navigation_type: navigation?.type || "unknown",\n      device_class: width < 640 ? "mobile" : width < 1024 ? "tablet" : "desktop",\n      sampled: false, lcp_ms: null, inp_ms: null, cls: null,\n      ttfb_ms: navigation?.responseStart ?? null, fcp_ms: null,\n      route_transition_ms: null, critical_api_ms: Math.max(0, performance.now() - started),\n      api_request_id: response.headers.get("x-request-id")\n    };\n  }\n\n  async function api(path, options = {}) {\n    const started = performance.now();\n    const response = await fetch(path, { credentials: "same-origin", ...options });\n    recordTelemetry(started, response);\n    let body = null;\n    if (response.status !== 204) {\n      try { body = await response.json(); } catch (_) { body = null; }\n    }\n    if (!response.ok) {\n      const error = new Error(body?.error?.message || `Request failed (${response.status})`);\n      error.status = response.status;\n      error.details = body?.error?.details || [];\n      throw error;\n    }\n    return body;\n  }\n\n  function formatDate(value, timezone) {\n    if (!value) return "No due date";\n    try {\n      return new Intl.DateTimeFormat(undefined, {\n        dateStyle: "medium", timeStyle: "short", timeZone: timezone\n      }).format(new Date(value));\n    } catch (_) { return "Date unavailable"; }\n  }\n\n  function taskDestination(task) {\n    // Only same-page destinations are accepted; arbitrary API-provided URLs are never used.\n    if (["#profile", "#tasks", "#submissions", "#assets"].includes(task.destination_path)) {\n      return task.destination_path;\n    }\n    if (["profile", "biography"].includes(task.task_type)) return "#profile";\n    if (["headshot", "slides", "supporting_document"].includes(task.task_type)) return "#assets";\n    return "#tasks";\n  }\n\n  function renderTasks(tasks, timezone) {\n    const list = byId("task-list");\n    list.replaceChildren();\n    const outstanding = tasks.filter((task) => !["completed", "waived"].includes(task.state));\n    byId("task-count").textContent = String(outstanding.length);\n    if (!outstanding.length) {\n      list.append(make("li", "You’re all caught up. There are no outstanding tasks.", "empty"));\n      return;\n    }\n    outstanding.forEach((task) => {\n      const item = make("li", undefined, "item-card");\n      const heading = make("h3", task.title);\n      const help = task.help_text ? make("p", task.help_text) : null;\n      const meta = make("p", undefined, "item-meta");\n      const overdue = task.due_at_ms !== null && task.due_at_ms < Date.now();\n      const dueSoon = task.due_at_ms !== null && task.due_at_ms >= Date.now()\n        && task.due_at_ms - Date.now() <= 7 * 24 * 60 * 60 * 1000;\n      const stateText = overdue ? "Overdue" : dueSoon ? "Due soon" : "Outstanding";\n      meta.append(\n        make("span", stateText, `state-badge${overdue ? " overdue" : ""}`),\n        make("span", `Due ${formatDate(task.due_at_ms, timezone)} · ${timezone}`)\n      );\n      const action = make("a", task.action_label || "Complete task", "task-link");\n      action.href = taskDestination(task);\n      item.append(heading);\n      if (help) item.append(help);\n      item.append(meta, action);\n      list.append(item);\n    });\n  }\n\n  function renderSubmissions(submissions) {\n    const list = byId("submission-list");\n    list.replaceChildren();\n    if (!submissions.length) {\n      list.append(make("li", "No proposals are connected to this account yet.", "empty"));\n      return;\n    }\n    submissions.forEach((submission) => {\n      const item = make("li", undefined, "item-card");\n      item.append(\n        make("h3", submission.proposal_title),\n        make("p", submission.status.replaceAll("_", " "), "state-badge")\n      );\n      list.append(item);\n    });\n  }\n\n  function fillSubmissionChoices(submissions) {\n    ["slides-submission", "document-submission"].forEach((id) => {\n      const select = byId(id);\n      const selected = select.value;\n      select.replaceChildren(new Option("Choose a session", ""));\n      submissions.forEach((submission) => select.add(new Option(submission.proposal_title, submission.id)));\n      if ([...select.options].some((option) => option.value === selected)) select.value = selected;\n    });\n  }\n\n  function fillProfile(profile) {\n    const form = byId("profile-form");\n    ["display_name", "job_title", "company", "location", "biography"].forEach((name) => {\n      form.elements[name].value = profile[name] || "";\n    });\n    form.elements.website.value = profile.links?.[0] || "";\n    state.version = profile.version;\n    updateBiographyCount();\n    clearErrors();\n    byId("stale-warning").hidden = true;\n  }\n\n  function renderPortal(portal) {\n    state.portal = portal;\n    const event = portal.event;\n    byId("portal-title").textContent = `Welcome, ${portal.profile.display_name || "speaker"}`;\n    const eventDates = `${formatDate(event.starts_at_ms, event.time_zone)}–${formatDate(event.ends_at_ms, event.time_zone)}`;\n    byId("event-summary").textContent = `${event.name} · ${eventDates}`;\n    byId("event-timezone").textContent = `All deadlines shown in ${event.time_zone}.`;\n    const tasks = portal.tasks || [];\n    const completed = portal.completed_tasks;\n    const total = portal.total_tasks;\n    byId("progress-count").textContent = `${completed} of ${total} complete`;\n    byId("progress").max = Math.max(total, 1);\n    byId("progress").value = completed;\n    const upcoming = tasks.filter((task) => task.state === "open" && task.due_at_ms !== null)\n      .sort((left, right) => left.due_at_ms - right.due_at_ms)[0];\n    byId("next-deadline").textContent = upcoming\n      ? `Next: ${upcoming.title}, ${formatDate(upcoming.due_at_ms, event.time_zone)} · ${event.time_zone}`\n      : "No upcoming deadline.";\n    renderTasks(tasks, event.time_zone);\n    renderSubmissions(portal.submissions || []);\n    fillSubmissionChoices(portal.submissions || []);\n    fillProfile(portal.profile);\n    byId("auth-state").hidden = true;\n    byId("portal").hidden = false;\n  }\n\n  function announceOnboardingChange() {\n    const eventId = state.portal?.event?.id;\n    if (!eventId || !("BroadcastChannel" in window)) return;\n    const channel = new BroadcastChannel(`sessionbuddy:onboarding:${eventId}`);\n    channel.postMessage({ type: "snapshot-invalidated" });\n    channel.close();\n  }\n\n  function clearErrors() {\n    byId("error-summary").hidden = true;\n    byId("error-summary").querySelector("ul").replaceChildren();\n    byId("profile-form").querySelectorAll("[aria-invalid]").forEach((field) => field.removeAttribute("aria-invalid"));\n    byId("profile-form").querySelectorAll(".field-error").forEach((node) => { node.textContent = ""; });\n  }\n\n  function showErrors(errors) {\n    clearErrors();\n    const summary = byId("error-summary");\n    const list = summary.querySelector("ul");\n    errors.forEach(({ field, message }) => {\n      const input = byId(field.replaceAll("_", "-"));\n      if (!input) return;\n      input.setAttribute("aria-invalid", "true");\n      const error = byId(`${field.replaceAll("_", "-")}-error`);\n      if (error) error.textContent = message;\n      const link = make("a", message); link.href = `#${input.id}`;\n      const item = document.createElement("li"); item.append(link); list.append(item);\n    });\n    summary.hidden = false;\n    summary.focus();\n  }\n\n  function clientErrors(values) {\n    const errors = [];\n    if (!values.display_name.trim()) errors.push({ field: "display_name", message: "Enter your name." });\n    if (!values.biography.trim()) errors.push({ field: "biography", message: "Enter your biography." });\n    if (values.website) {\n      try {\n        const url = new URL(values.website);\n        if (!["http:", "https:"].includes(url.protocol)) throw new Error();\n      } catch (_) { errors.push({ field: "website", message: "Enter a complete HTTP or HTTPS website address." }); }\n    }\n    return errors;\n  }\n\n  async function load() {\n    setStatus("Checking your secure session…");\n    try {\n      const session = await api("/api/v1/session");\n      state.csrf = session.csrf_token;\n      const portal = await api("/api/v1/speaker/portal");\n      renderPortal(portal);\n      await loadAssets();\n      setStatus("Your speaker portal is ready.", "success");\n    } catch (error) {\n      if (error.status === 401 || error.status === 404) {\n        byId("portal").hidden = true;\n        byId("auth-state").hidden = false;\n        setStatus("Speaker access is required to view this portal.", "error");\n      } else {\n        setStatus("We couldn’t load your portal. Try again in a moment.", "error");\n      }\n    }\n  }\n\n  byId("profile-form").addEventListener("submit", async (event) => {\n    event.preventDefault();\n    const button = byId("save-profile");\n    const values = Object.fromEntries(new FormData(event.currentTarget));\n    values.links = values.website ? [values.website] : [];\n    delete values.website;\n    const errors = clientErrors(values);\n    if (errors.length) { showErrors(errors); return; }\n    clearErrors();\n    button.disabled = true;\n    button.textContent = "Saving…";\n    try {\n      const profile = await api("/api/v1/speaker/profile", {\n        method: "PATCH",\n        headers: {\n          "content-type": "application/json", "x-csrf-token": state.csrf,\n          "idempotency-key": `${crypto.randomUUID()}-${crypto.randomUUID()}`\n        },\n        body: JSON.stringify({ ...values, version: state.version })\n      });\n      fillProfile(profile);\n      const portal = await api("/api/v1/speaker/portal");\n      renderPortal(portal);\n      announceOnboardingChange();\n      setStatus("Profile saved. Related onboarding tasks are up to date.", "success");\n    } catch (error) {\n      if (error.status === 409 || error.status === 412) {\n        byId("stale-warning").hidden = false;\n        byId("stale-warning").focus?.();\n        setStatus("Your profile was not saved because a newer version exists.", "error");\n      } else if (error.status === 401) {\n        byId("portal").hidden = true; byId("auth-state").hidden = false;\n        setStatus("Your session ended before the profile could be saved.", "error");\n      } else if (error.status === 422 && error.details.length) {\n        showErrors(error.details.map((detail) => ({ field: detail.field || detail.loc?.at(-1), message: detail.message || "Check this field." })));\n        setStatus("Your profile has errors. Nothing was saved.", "error");\n      } else {\n        setStatus("We couldn’t save your profile. Your entries remain on this page.", "error");\n      }\n    } finally {\n      button.disabled = false;\n      button.textContent = "Save profile";\n    }\n  });\n\n  byId("reload-profile").addEventListener("click", async () => {\n    try {\n      const portal = await api("/api/v1/speaker/portal");\n      renderPortal(portal);\n      setStatus("Latest profile loaded. Review it before saving.");\n    } catch (_) { setStatus("We couldn’t reload the latest profile.", "error"); }\n  });\n\n  byId("start-demo").addEventListener("click", async () => {\n    location.assign(`/sign-in?redirect=${encodeURIComponent(location.pathname)}`);\n  });\n\n  function updateBiographyCount() {\n    const length = byId("biography").value.length;\n    byId("biography-count").textContent = `${length.toLocaleString()} of 5,000 characters`;\n  }\n  byId("biography").addEventListener("input", updateBiographyCount);\n\n  function safeUploadUrl(value) {\n    try {\n      const url = new URL(value, location.origin);\n      const trustedR2 = url.protocol === "https:" && url.hostname.endsWith(".r2.cloudflarestorage.com");\n      return url.origin === location.origin || trustedR2 ? url : null;\n    } catch (_) { return null; }\n  }\n\n  function safeUploadHeaders(headers, contentType) {\n    const safe = { "content-type": contentType };\n    Object.entries(headers || {}).forEach(([name, value]) => {\n      const lower = name.toLowerCase();\n      if (["content-type", "x-amz-checksum-sha256"].includes(lower)) safe[lower] = String(value);\n    });\n    return safe;\n  }\n\n  function uploadFile(url, method, headers, file, progress) {\n    return new Promise((resolve, reject) => {\n      if (method !== "PUT") { reject(new Error("Upload authorization used an unsupported method.")); return; }\n      const request = new XMLHttpRequest();\n      request.open("PUT", url.toString());\n      request.withCredentials = false;\n      Object.entries(headers).forEach(([name, value]) => request.setRequestHeader(name, value));\n      request.upload.addEventListener("progress", (event) => {\n        if (event.lengthComputable) progress.value = Math.round((event.loaded / event.total) * 100);\n      });\n      request.addEventListener("load", () => request.status >= 200 && request.status < 300\n        ? resolve() : reject(new Error(`Storage upload failed (${request.status}).`)));\n      request.addEventListener("error", () => reject(new Error("Storage upload could not be reached.")));\n      request.send(file);\n    });\n  }\n\n  async function checksum(file) {\n    const digest = await crypto.subtle.digest("SHA-256", await file.arrayBuffer());\n    return [...new Uint8Array(digest)].map((byte) => byte.toString(16).padStart(2, "0")).join("");\n  }\n\n  function validateFile(kind, file) {\n    const rule = uploadRules[kind];\n    if (!file) return "Choose a file to upload.";\n    if (!rule.types.has(file.type)) return "This file type is not allowed.";\n    if (file.size <= 0 || file.size > rule.max) return `File must be larger than zero and no more than ${Math.round(rule.max / 1024 / 1024)} MB.`;\n    return null;\n  }\n\n  function taskForKind(kind) {\n    return state.portal?.tasks?.find((task) => task.task_type === kind && task.state === "open")?.id || null;\n  }\n\n  async function loadAssets() {\n    const status = byId("asset-status");\n    try {\n      const eventId = state.portal?.event?.id;\n      if (!eventId) throw new Error("Speaker event is unavailable.");\n      const result = await api(`/api/v1/speaker/events/${encodeURIComponent(eventId)}/assets`);\n      const assets = result.data || [];\n      const list = byId("asset-list"); list.replaceChildren();\n      if (!assets.length) list.append(make("li", "No clean assets uploaded yet.", "empty"));\n      assets.forEach((asset) => {\n        const item = document.createElement("li");\n        item.append(make("strong", asset.filename), make("span", asset.state.replaceAll("_", " ")));\n        list.append(item);\n      });\n      status.textContent = `${assets.length} current clean asset${assets.length === 1 ? "" : "s"}.`;\n      status.classList.remove("error");\n    } catch (_) {\n      status.textContent = "Current assets could not be loaded. Uploads are unavailable until this reconnects.";\n      status.classList.add("error");\n    }\n  }\n\n  document.querySelectorAll(".upload-card").forEach((form) => form.addEventListener("submit", async (event) => {\n    event.preventDefault();\n    const kind = form.dataset.kind;\n    const file = form.elements.file.files[0];\n    const status = form.querySelector(".upload-status");\n    const progress = form.querySelector("progress");\n    const button = form.querySelector("button[type=submit]");\n    const validation = validateFile(kind, file);\n    if (validation) { status.textContent = validation; status.classList.add("error"); return; }\n    button.disabled = true; progress.hidden = false; progress.value = 0;\n    status.classList.remove("error"); status.textContent = "Checking file integrity…";\n    try {\n      const eventId = state.portal?.event?.id;\n      if (!eventId) throw new Error("Speaker event is unavailable.");\n      const authorization = await api(`/api/v1/speaker/events/${encodeURIComponent(eventId)}/upload-authorizations`, {\n        method: "POST",\n        headers: { "content-type": "application/json", "x-csrf-token": state.csrf, "idempotency-key": `${crypto.randomUUID()}-${crypto.randomUUID()}` },\n        body: JSON.stringify({\n          kind, submission_id: form.elements.submission_id?.value || null,\n          task_id: taskForKind(kind), filename: file.name, content_type: file.type,\n          byte_size: file.size, checksum_sha256: await checksum(file)\n        })\n      });\n      const uploadUrl = safeUploadUrl(authorization.upload_url);\n      if (!uploadUrl || authorization.expires_at_ms <= Date.now()) throw new Error("Upload authorization is invalid or expired.");\n      status.textContent = "Uploading…";\n      await uploadFile(uploadUrl, authorization.method, safeUploadHeaders(authorization.headers, file.type), file, progress);\n      status.textContent = "Upload received. Starting safety checks…";\n      const completion = await api(`/api/v1/speaker/events/${encodeURIComponent(eventId)}/upload-intents/${encodeURIComponent(authorization.intent_id)}/complete`, {\n        method: "POST", headers: { "content-type": "application/json", "x-csrf-token": state.csrf, "idempotency-key": `${crypto.randomUUID()}-${crypto.randomUUID()}` }, body: "{}"\n      });\n      progress.value = 100;\n      if (completion.state === "rejected") {\n        status.textContent = "This file was rejected by the safety scan. It was not made available. Choose a different file.";\n        status.classList.add("error");\n      } else if (completion.state === "clean") {\n        status.textContent = "Upload checked and ready.";\n      } else {\n        status.textContent = "Upload complete. The file is being checked before it becomes current.";\n      }\n      form.elements.file.value = "";\n      await loadAssets();\n      const portal = await api("/api/v1/speaker/portal"); renderPortal(portal);\n      announceOnboardingChange();\n    } catch (error) {\n      status.textContent = error.message || "Upload failed. Choose the file and try again.";\n      status.classList.add("error");\n    } finally { button.disabled = false; }\n  }));\n  load();\n})();\n'

SPEAKER_CSS = ':root { color-scheme: light; font-family: Inter, ui-sans-serif, system-ui, sans-serif; color: #172033; background: #f5f6fa; }\n* { box-sizing: border-box; }\nhtml { scroll-behavior: smooth; }\nbody { margin: 0; line-height: 1.5; }\n.shell { width: min(72rem, calc(100% - 2rem)); margin-inline: auto; }\n.skip-link { position: fixed; top: -5rem; left: 1rem; z-index: 10; padding: .7rem 1rem; background: white; color: #163b8c; }\n.skip-link:focus { top: .5rem; }\n.site-header { background: #172033; color: white; }\n.header-layout { min-height: 4.25rem; display: flex; align-items: center; justify-content: space-between; gap: 1rem; }\n.brand { color: white; font-size: 1.05rem; font-weight: 800; text-decoration: none; }\nnav { display: flex; flex-wrap: wrap; gap: .2rem; }\nnav a { min-height: 2.75rem; display: inline-flex; align-items: center; padding: .5rem .75rem; border-radius: .5rem; color: #e8edff; text-decoration: none; }\nnav a[aria-current="page"] { background: #34425e; color: white; }\nmain { padding-block: 1.5rem 4rem; }\n.status, .state-panel { margin-bottom: 1rem; padding: 1rem; border: 1px solid #cbd5ea; border-left: .3rem solid #3159d9; border-radius: .6rem; background: #edf2ff; }\n.status.error, .error-summary, .stale-warning { border-color: #b42318; background: #fff0ee; color: #7a271a; }\n.status.success { border-color: #168253; background: #ebf8f1; color: #155c3e; }\n.hero { display: grid; grid-template-columns: minmax(0, 1.6fr) minmax(17rem, .8fr); gap: 1.25rem; align-items: end; margin: 1.5rem 0; }\n.eyebrow { margin: 0 0 .3rem; color: #5e6b83; font-size: .78rem; font-weight: 800; letter-spacing: .09em; text-transform: uppercase; }\nh1, h2, h3 { line-height: 1.15; }\nh1 { margin: 0; font-size: clamp(2rem, 5vw, 3.5rem); }\nh2 { margin: .15rem 0 .75rem; }\n.lede { max-width: 44rem; color: #4e5b72; font-size: 1.08rem; }\n.timezone, .help, .field-meta { color: #59667c; font-size: .9rem; }\n.progress-card, .panel { padding: 1.35rem; border: 1px solid #dde2ec; border-radius: 1rem; background: white; box-shadow: 0 .45rem 1.6rem rgb(30 43 73 / 7%); }\n.progress-card { display: grid; gap: .5rem; }\n.progress-card strong { font-size: 1.25rem; }\nprogress { width: 100%; height: .8rem; accent-color: #3159d9; }\n.portal-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 1.25rem; }\n.profile-panel { grid-column: 1 / -1; }\n.section-heading { display: flex; justify-content: space-between; gap: 1rem; align-items: start; }\n.count-badge, .state-badge { display: inline-flex; align-items: center; min-height: 1.8rem; padding: .15rem .55rem; border-radius: 999px; background: #e9eeff; color: #274aa9; font-size: .82rem; font-weight: 750; }\n.state-badge.overdue { background: #fee4e2; color: #912018; }\n.state-badge.complete { background: #dcf6e9; color: #11613f; }\n.item-list { display: grid; gap: .75rem; margin: 0; padding: 0; list-style: none; }\n.item-card { padding: 1rem; border: 1px solid #e0e5ee; border-radius: .7rem; }\n.item-card h3 { margin: 0 0 .35rem; font-size: 1rem; }\n.item-meta { display: flex; flex-wrap: wrap; align-items: center; gap: .4rem .8rem; margin: .5rem 0 0; color: #59667c; font-size: .9rem; }\n.empty { padding: 1rem; border-radius: .7rem; background: #f0f7f3; color: #275b43; }\n.task-link { display: inline-flex; align-items: center; min-height: 2.75rem; margin-top: .65rem; font-weight: 750; }\n.form-grid { display: grid; grid-template-columns: minmax(8rem, .35fr) minmax(0, 1fr); gap: .5rem 1.25rem; align-items: start; }\n.form-grid > label { padding-top: .8rem; font-weight: 700; }\n.form-grid > label span { color: #7a271a; font-size: .8rem; font-weight: 600; }\ninput, textarea, select { width: 100%; min-height: 2.75rem; padding: .7rem .8rem; border: 1px solid #9ca8bc; border-radius: .55rem; background: white; color: inherit; font: inherit; }\ntextarea { resize: vertical; }\ninput[readonly] { background: #eef1f6; color: #4e5b72; }\ninput[aria-invalid="true"], textarea[aria-invalid="true"] { border: 2px solid #b42318; }\n.field-meta { display: flex; justify-content: space-between; gap: 1rem; }\n.field-meta p { margin: .3rem 0; }\n.field-error { min-height: 1.4em; margin: .25rem 0 .65rem; color: #9b241a; font-weight: 650; }\n.error-summary, .stale-warning { margin: 1rem 0; padding: 1rem; border: 1px solid; border-radius: .65rem; }\n.error-summary h3, .stale-warning p { margin-top: 0; }\n.error-summary a { color: inherit; }\n.actions { display: flex; justify-content: flex-end; margin-top: 1rem; }\n.inline-status { margin: 1rem 0; padding: .75rem; border-left: .25rem solid #3159d9; background: #edf2ff; }\n.inline-status.error { border-color: #b42318; background: #fff0ee; color: #7a271a; }\n.asset-list { display: grid; gap: .5rem; margin: 0 0 1.25rem; padding: 0; list-style: none; }\n.asset-list li { display: flex; flex-wrap: wrap; justify-content: space-between; gap: .5rem; padding: .75rem; border: 1px solid #e0e5ee; border-radius: .65rem; }\n.upload-grid { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 1rem; }\n.upload-card { display: flex; flex-direction: column; gap: .65rem; padding: 1rem; border: 1px solid #dce1eb; border-radius: .75rem; }\n.upload-card h3, .upload-card p { margin: 0; }\n.upload-card label { font-weight: 700; }\n.upload-card button { margin-top: auto; }\n.upload-card progress { width: 100%; accent-color: #3159d9; }\n.upload-status { min-height: 1.5em; color: #59667c; }\n.upload-status.error { color: #9b241a; font-weight: 650; }\nbutton, .button { min-height: 2.75rem; display: inline-flex; align-items: center; justify-content: center; padding: .7rem 1rem; border: 0; border-radius: .55rem; background: #3159d9; color: white; font: inherit; font-weight: 750; text-decoration: none; cursor: pointer; }\nbutton.secondary { border: 1px solid #aeb8ca; background: white; color: #263550; }\nbutton:disabled { cursor: wait; opacity: .55; }\na { color: #234fc6; }\n:where(a, button, input, textarea, select):focus-visible { outline: 3px solid #e69b00; outline-offset: 3px; }\n[hidden] { display: none !important; }\n@media (max-width: 48rem) {\n  .header-layout { align-items: flex-start; flex-direction: column; padding-block: .85rem; }\n  nav { width: 100%; overflow-x: auto; flex-wrap: nowrap; }\n  .hero, .portal-grid, .form-grid { grid-template-columns: 1fr; }\n  .form-grid > label { padding: .2rem 0 0; }\n  .profile-panel { grid-column: auto; }\n  .field-meta { display: block; }\n  .actions button, .task-link { width: 100%; }\n  .upload-grid { grid-template-columns: 1fr; }\n}\n@media (prefers-reduced-motion: reduce) { html { scroll-behavior: auto; } *, *::before, *::after { transition: none !important; } }\n'

ADMIN_ONBOARDING_HTML = '<!doctype html>\n<html lang="en">\n<head>\n  <meta charset="utf-8">\n  <meta name="viewport" content="width=device-width, initial-scale=1">\n  <meta name="color-scheme" content="light">\n  <title>Speaker onboarding · SessionBuddy</title>\n  <link rel="stylesheet" href="/admin/onboarding/assets/onboarding.css?v=1">\n  <script src="/admin/onboarding/assets/onboarding.js?v=1" defer></script>\n</head>\n<body>\n  <a class="skip-link" href="#main">Skip to content</a>\n  <header class="site-header">\n    <div class="shell header-layout">\n      <a class="brand" href="/admin/programs">SessionBuddy</a>\n      <nav aria-label="Administration">\n        <a href="/admin/programs">Programs</a>\n        <a id="onboarding-link" href="#" aria-current="page">Onboarding</a>\n        <a href="/reviews">Evaluations</a>\n      </nav>\n    </div>\n  </header>\n  <main id="main" class="shell" tabindex="-1">\n    <section class="hero" aria-labelledby="page-title">\n      <div><p class="eyebrow">Event operations</p><h1 id="page-title">Speaker onboarding</h1><p id="event-name">See who is blocked and what they still owe.</p></div>\n      <div class="connection"><span id="connection-dot" aria-hidden="true"></span><strong id="connection-state">Connecting</strong><span id="last-refreshed">Not refreshed yet</span></div>\n    </section>\n    <div id="status" class="status" role="status" aria-live="polite">Checking your admin session…</div>\n    <section class="summary-grid" aria-label="Onboarding summary">\n      <article><span>Complete</span><strong id="count-complete">—</strong></article>\n      <article><span>Incomplete</span><strong id="count-incomplete">—</strong></article>\n      <article><span>Overdue</span><strong id="count-overdue">—</strong></article>\n      <article><span>Due soon</span><strong id="count-due-soon">—</strong></article>\n    </section>\n    <section class="panel" aria-labelledby="filters-title">\n      <div class="section-heading"><div><p class="eyebrow">Current view</p><h2 id="filters-title">Filters</h2></div><button id="refresh" class="secondary" type="button">Refresh now</button></div>\n      <form id="filters" class="filters">\n        <label for="state">Task state<select id="state" name="state"><option value="">All tasks</option><option value="open">All outstanding</option><option value="completed">Completed</option><option value="overdue">Overdue outstanding</option><option value="due_soon">Due-soon outstanding</option></select></label>\n        <label for="task-type">Task type<select id="task-type" name="task_type"><option value="">All task types</option><option value="biography">Biography</option><option value="profile">Profile</option><option value="headshot">Headshot</option><option value="slides">Slides</option><option value="supporting_document">Supporting document</option></select></label>\n        <div class="filter-actions"><button type="submit">Apply filters</button><button id="clear-filters" class="secondary" type="button">Clear</button></div>\n      </form>\n    </section>\n    <section class="panel" aria-labelledby="list-title" aria-busy="true" id="results-panel">\n      <div class="section-heading"><div><p class="eyebrow">Action queue</p><h2 id="list-title">Speakers needing attention</h2></div><span id="result-count" class="count">—</span></div>\n      <div class="desktop-table"><table><thead><tr><th scope="col">Speaker</th><th scope="col">Session</th><th scope="col">Missing task</th><th scope="col">Due</th><th scope="col">Last activity</th><th scope="col">Action</th></tr></thead><tbody id="onboarding-rows"><tr><td colspan="6">Loading…</td></tr></tbody></table></div>\n      <ul id="onboarding-cards" class="mobile-cards" aria-label="Onboarding results"><li>Loading…</li></ul>\n      <div id="empty" class="empty" hidden><strong>No speakers match this view.</strong><p>Try clearing a filter, or check again after new onboarding activity.</p></div>\n      <div class="pagination"><button id="load-more" class="secondary" type="button" hidden>Load more</button></div>\n    </section>\n  </main>\n</body>\n</html>\n'

ADMIN_ONBOARDING_JS = '(() => {\n  "use strict";\n  const REFRESH_MS = 5000;\n  const ALLOWED_STATES = new Set(["", "open", "completed", "overdue", "due_soon"]);\n  const ALLOWED_TASK_TYPES = new Set(["", "biography", "profile", "headshot", "slides", "supporting_document"]);\n  const routeMatch = location.pathname.match(/^\\/admin\\/events\\/([^/]+)\\/onboarding$/);\n  let eventId = "";\n  try { eventId = routeMatch ? decodeURIComponent(routeMatch[1]) : ""; } catch (_) { eventId = ""; }\n  if (!/^[A-Za-z0-9_.-]{1,128}$/.test(eventId)) eventId = "";\n  const state = { timer: null, loading: false, cursor: null, rows: [], lastSuccess: null, timeZone: "UTC", csrf: "", channel: null };\n  const byId = (id) => document.getElementById(id);\n  const make = (tag, value, className) => { const node = document.createElement(tag); if (value !== undefined) node.textContent = value; if (className) node.className = className; return node; };\n\n  function setStatus(message, error = false) {\n    byId("status").textContent = message;\n    byId("status").classList.toggle("error", error);\n  }\n\n  function setConnection(kind, label) {\n    byId("connection-dot").className = kind;\n    byId("connection-state").textContent = label;\n    byId("last-refreshed").textContent = state.lastSuccess\n      ? `Last refreshed ${state.lastSuccess.toLocaleTimeString()}` : "Not refreshed yet";\n  }\n\n  function recordTelemetry(started, response) {\n    const navigation = performance.getEntriesByType("navigation")[0];\n    const width = innerWidth;\n    window.__sessionbuddyTelemetryDraft = {\n      schema_version: 1, page_template: "/admin/events/{event_id}/onboarding",\n      navigation_type: navigation?.type || "unknown",\n      device_class: width < 640 ? "mobile" : width < 1024 ? "tablet" : "desktop",\n      sampled: false, lcp_ms: null, inp_ms: null, cls: null,\n      ttfb_ms: navigation?.responseStart ?? null, fcp_ms: null, route_transition_ms: null,\n      critical_api_ms: Math.max(0, performance.now() - started),\n      api_request_id: response.headers.get("x-request-id")\n    };\n  }\n\n  async function api(path, options = {}) {\n    const started = performance.now();\n    const response = await fetch(path, { ...options, credentials: "same-origin", headers: { accept: "application/json", ...(options.headers || {}) } });\n    recordTelemetry(started, response);\n    let body = null;\n    try { body = await response.json(); } catch (_) { body = null; }\n    if (!response.ok) {\n      const error = new Error(body?.error?.message || `Request failed (${response.status})`);\n      error.status = response.status; throw error;\n    }\n    return body;\n  }\n\n  function selectedFilters() {\n    const selectedState = byId("state").value;\n    const taskType = byId("task-type").value;\n    return {\n      state: ALLOWED_STATES.has(selectedState) ? selectedState : "",\n      task_type: ALLOWED_TASK_TYPES.has(taskType) ? taskType : ""\n    };\n  }\n\n  function query(cursor = null) {\n    const params = new URLSearchParams();\n    const filters = selectedFilters();\n    if (filters.state) params.set("state", filters.state);\n    if (filters.task_type) params.set("task_type", filters.task_type);\n    if (cursor) params.set("cursor", cursor);\n    return params.toString();\n  }\n\n  function preserveFilters() {\n    const params = new URLSearchParams();\n    const filters = selectedFilters();\n    if (filters.state) params.set("state", filters.state);\n    if (filters.task_type) params.set("task_type", filters.task_type);\n    history.replaceState(null, "", `${location.pathname}${params.size ? `?${params}` : ""}`);\n  }\n\n  function formatDate(value) {\n    if (value === null || value === undefined) return "No due date";\n    try {\n      return new Intl.DateTimeFormat(undefined, {\n        dateStyle: "medium", timeStyle: "short", timeZone: state.timeZone\n      }).format(new Date(value));\n    } catch (_) { return "Date unavailable"; }\n  }\n\n  function isOverdue(row) { return row.state === "overdue"; }\n\n  function addTableRow(row) {\n    const tr = document.createElement("tr");\n    const speaker = document.createElement("td");\n    const link = make("a", row.display_name); link.href = speakerLink(row); speaker.append(link);\n    tr.append(speaker);\n    [row.proposal_title, row.task_title, formatDate(row.due_at_ms), formatDate(row.last_activity_at_ms)].forEach((value, index) => {\n      const td = make("td", value, index === 1 ? "task-name" : index === 2 && isOverdue(row) ? "overdue" : ""); tr.append(td);\n    });\n    const action = document.createElement("td");\n    const button = make("button", "Send reminder", "compact secondary"); button.type = "button";\n    button.addEventListener("click", () => sendReminder(row, button)); action.append(button); tr.append(action);\n    byId("onboarding-rows").append(tr);\n  }\n\n  function addCard(row) {\n    const item = document.createElement("li");\n    const heading = document.createElement("h3");\n    const speaker = make("a", row.display_name); speaker.href = speakerLink(row); heading.append(speaker); item.append(heading);\n    const list = document.createElement("dl");\n    [["Session", row.proposal_title], ["Missing", row.task_title], ["Due", formatDate(row.due_at_ms)], ["Last activity", formatDate(row.last_activity_at_ms)]].forEach(([label, value]) => {\n      list.append(make("dt", label), make("dd", value, label === "Due" && isOverdue(row) ? "overdue" : ""));\n    });\n    const reminder = make("button", "Send reminder", "compact secondary"); reminder.type = "button";\n    reminder.addEventListener("click", () => sendReminder(row, reminder));\n    item.append(list, reminder); byId("onboarding-cards").append(item);\n  }\n\n  function speakerLink(row) {\n    return `/admin/events/${encodeURIComponent(eventId)}/speakers/${encodeURIComponent(row.event_speaker_id)}`;\n  }\n\n  async function sendReminder(row, button) {\n    button.disabled = true;\n    try {\n      await api(`/api/v1/admin/events/${encodeURIComponent(eventId)}/speaker-tasks/${encodeURIComponent(row.task_id)}/reminders`, {\n        method: "POST",\n        headers: { "content-type": "application/json", "x-csrf-token": state.csrf, "idempotency-key": `${crypto.randomUUID()}-${crypto.randomUUID()}` },\n        body: "{}"\n      });\n      setStatus(`Reminder queued for ${row.display_name}.`);\n    } catch (error) {\n      setStatus(error.status === 404\n        ? "Reminder delivery is not connected in this environment yet. No message was sent."\n        : "The reminder could not be queued. No message was sent.", true);\n    } finally { button.disabled = false; }\n  }\n\n  function render(data, append) {\n    const summary = data.summary;\n    state.timeZone = data.time_zone;\n    byId("event-name").textContent = `${data.event_name} · Dates shown in ${data.time_zone}`;\n    byId("count-complete").textContent = summary.complete;\n    byId("count-incomplete").textContent = summary.incomplete;\n    byId("count-overdue").textContent = summary.overdue;\n    byId("count-due-soon").textContent = summary.due_soon;\n    const incoming = data.data;\n    if (!append) {\n      state.rows = [];\n      byId("onboarding-rows").replaceChildren();\n      byId("onboarding-cards").replaceChildren();\n    }\n    state.rows.push(...incoming);\n    incoming.forEach((row) => { addTableRow(row); addCard(row); });\n    byId("result-count").textContent = String(state.rows.length);\n    byId("empty").hidden = state.rows.length !== 0;\n    byId("load-more").hidden = !data.next_cursor;\n    state.cursor = data.next_cursor || null;\n  }\n\n  async function refresh({ append = false, announce = false } = {}) {\n    if (state.loading || document.hidden) return;\n    state.loading = true;\n    byId("results-panel").setAttribute("aria-busy", "true");\n    setConnection("", state.lastSuccess ? "Refreshing" : "Connecting");\n    try {\n      const filterQuery = query(append ? state.cursor : null);\n      const endpoint = `/api/v1/admin/events/${encodeURIComponent(eventId)}/onboarding`;\n      const data = await api(`${endpoint}${filterQuery ? `?${filterQuery}` : ""}`);\n      render(data, append);\n      state.lastSuccess = new Date(data.generated_at_ms);\n      setConnection("live", "Live snapshot");\n      setStatus(announce ? "Onboarding snapshot refreshed." : `${state.rows.length} speaker record${state.rows.length === 1 ? "" : "s"} shown.`);\n    } catch (error) {\n      const authMessage = error.status === 401 || error.status === 403\n        ? "Your admin session cannot access this onboarding dashboard."\n        : "Live refresh failed. Showing the last successful snapshot while reconnecting.";\n      setStatus(authMessage, true);\n      setConnection("stale", error.status === 401 || error.status === 403 ? "Access unavailable" : "Reconnecting");\n    } finally {\n      state.loading = false;\n      byId("results-panel").setAttribute("aria-busy", "false");\n    }\n  }\n\n  function startPolling() {\n    clearInterval(state.timer);\n    if (!document.hidden) state.timer = setInterval(() => refresh(), REFRESH_MS);\n  }\n\n  function connectInvalidations() {\n    if (!("BroadcastChannel" in window)) return;\n    state.channel?.close();\n    state.channel = new BroadcastChannel(`sessionbuddy:onboarding:${eventId}`);\n    state.channel.addEventListener("message", () => refresh());\n  }\n\n  function initializeFilters() {\n    const params = new URLSearchParams(location.search);\n    const selectedState = params.get("state") || "";\n    const taskType = params.get("task_type") || "";\n    byId("state").value = ALLOWED_STATES.has(selectedState) ? selectedState : "";\n    byId("task-type").value = ALLOWED_TASK_TYPES.has(taskType) ? taskType : "";\n    preserveFilters();\n  }\n\n  byId("filters").addEventListener("submit", (event) => { event.preventDefault(); preserveFilters(); refresh({ announce: true }); });\n  byId("clear-filters").addEventListener("click", () => { byId("filters").reset(); preserveFilters(); refresh({ announce: true }); });\n  byId("refresh").addEventListener("click", () => refresh({ announce: true }));\n  byId("load-more").addEventListener("click", () => refresh({ append: true, announce: true }));\n  document.addEventListener("visibilitychange", () => {\n    startPolling();\n    if (document.hidden) setConnection("", "Updates paused");\n    else refresh({ announce: true });\n  });\n  window.addEventListener("online", () => refresh({ announce: true }));\n  window.addEventListener("offline", () => setConnection("stale", "Offline · snapshot retained"));\n  window.addEventListener("pageshow", (event) => { if (event.persisted) refresh({ announce: true }); });\n  window.addEventListener("sessionbuddy:onboarding-invalidated", () => refresh());\n\n  async function initialize() {\n    if (!eventId) {\n      setStatus("This onboarding dashboard link is invalid. Return to Programs and choose an event.", true);\n      setConnection("stale", "Invalid event link");\n      return;\n    }\n    byId("onboarding-link").href = `/admin/events/${encodeURIComponent(eventId)}/onboarding`;\n    initializeFilters();\n    try {\n      const session = await api("/api/v1/session");\n      state.csrf = session.csrf_token;\n      await refresh();\n      connectInvalidations();\n      startPolling();\n    } catch (error) {\n      setStatus(error.status === 401 ? "Sign in as an event administrator to continue." : "We couldn’t verify your admin session.", true);\n      setConnection("stale", "Access unavailable");\n    }\n  }\n  initialize();\n})();\n'

ADMIN_ONBOARDING_CSS = ':root { color-scheme: light; font-family: Inter, ui-sans-serif, system-ui, sans-serif; color: #172033; background: #f4f6fb; }\n* { box-sizing: border-box; }\nbody { margin: 0; line-height: 1.5; }\n.shell { width: min(76rem, calc(100% - 2rem)); margin-inline: auto; }\n.skip-link { position: fixed; top: -5rem; left: 1rem; z-index: 10; padding: .7rem 1rem; background: white; color: #173f9f; }\n.skip-link:focus { top: .5rem; }\n.site-header { background: #172033; color: white; }\n.header-layout { min-height: 4.25rem; display: flex; align-items: center; justify-content: space-between; gap: 1rem; }\n.brand { color: white; font-weight: 800; text-decoration: none; }\nnav { display: flex; flex-wrap: wrap; gap: .2rem; }\nnav a { min-height: 2.75rem; display: inline-flex; align-items: center; padding: .5rem .75rem; border-radius: .5rem; color: #e8edff; text-decoration: none; }\nnav a[aria-current="page"] { background: #34425e; color: white; }\nmain { padding-block: 2rem 4rem; }\n.hero { display: flex; justify-content: space-between; align-items: end; gap: 1.5rem; }\n.eyebrow { margin: 0 0 .25rem; color: #63708a; font-size: .78rem; font-weight: 800; letter-spacing: .09em; text-transform: uppercase; }\nh1, h2 { margin: .15rem 0 .5rem; line-height: 1.15; }\nh1 { font-size: clamp(2rem, 5vw, 3.2rem); }\n.connection { min-width: 13rem; display: grid; grid-template-columns: auto 1fr; gap: .1rem .55rem; align-items: center; padding: .8rem 1rem; border: 1px solid #d8deea; border-radius: .75rem; background: white; }\n.connection span:last-child { grid-column: 2; color: #5c687d; font-size: .85rem; }\n#connection-dot { width: .65rem; height: .65rem; border-radius: 50%; background: #d28619; }\n#connection-dot.live { background: #168253; }\n#connection-dot.stale { background: #b42318; }\n.status { margin: 1.25rem 0; padding: .8rem 1rem; border-left: .3rem solid #3159d9; background: #eaf0ff; }\n.status.error { border-color: #b42318; background: #fff0ee; color: #7a271a; }\n.summary-grid { display: grid; grid-template-columns: repeat(4, minmax(0, 1fr)); gap: 1rem; }\n.summary-grid article, .panel { border: 1px solid #dce1eb; border-radius: .9rem; background: white; box-shadow: 0 .4rem 1.5rem rgb(27 39 70 / 6%); }\n.summary-grid article { display: grid; gap: .2rem; padding: 1rem; }\n.summary-grid span { color: #5c687d; }\n.summary-grid strong { font-size: 1.8rem; }\n.panel { margin-top: 1.25rem; padding: 1.25rem; }\n.section-heading { display: flex; justify-content: space-between; align-items: start; gap: 1rem; }\n.filters { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)) auto; gap: 1rem; align-items: end; }\nlabel { display: grid; gap: .35rem; font-weight: 700; }\nselect { width: 100%; min-height: 2.75rem; padding: .65rem .75rem; border: 1px solid #aeb8ca; border-radius: .55rem; background: white; color: inherit; font: inherit; }\nbutton { min-height: 2.75rem; padding: .65rem 1rem; border: 0; border-radius: .55rem; background: #3159d9; color: white; font: inherit; font-weight: 750; cursor: pointer; }\nbutton.secondary { border: 1px solid #aeb8ca; background: white; color: #263550; }\nbutton.compact { min-height: 2.75rem; padding: .45rem .7rem; white-space: nowrap; }\nbutton:disabled { cursor: wait; opacity: .55; }\n.filter-actions { display: flex; gap: .5rem; }\n.count { min-width: 2rem; padding: .2rem .6rem; border-radius: 999px; background: #e9eeff; color: #274aa9; text-align: center; font-weight: 750; }\n.desktop-table { overflow-x: auto; }\ntable { width: 100%; border-collapse: collapse; }\nth, td { padding: .8rem; border-bottom: 1px solid #dce1eb; text-align: left; vertical-align: top; }\nth { color: #536079; font-size: .78rem; text-transform: uppercase; }\n.task-name { font-weight: 750; }\n.overdue { color: #9b241a; font-weight: 750; }\n.mobile-cards { display: none; margin: 0; padding: 0; list-style: none; }\n.mobile-cards li { padding: 1rem 0; border-bottom: 1px solid #dce1eb; }\n.mobile-cards h3 { margin: 0; }\n.mobile-cards dl { display: grid; grid-template-columns: 7rem 1fr; gap: .4rem; }\n.mobile-cards dt { color: #5c687d; }\n.mobile-cards dd { margin: 0; }\n.empty { margin-top: .8rem; padding: 1rem; border-radius: .7rem; background: #f1f4fa; }\n.empty p { margin-bottom: 0; }\n.pagination { display: flex; justify-content: center; margin-top: 1rem; }\n:where(a, button, select):focus-visible { outline: 3px solid #e69b00; outline-offset: 3px; }\n[hidden] { display: none !important; }\n@media (max-width: 48rem) {\n  .header-layout, .hero { align-items: flex-start; flex-direction: column; }\n  .header-layout { padding-block: .8rem; }\n  nav { width: 100%; overflow-x: auto; flex-wrap: nowrap; }\n  .connection { width: 100%; }\n  .summary-grid { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n  .filters { grid-template-columns: 1fr; }\n  .filter-actions, .filter-actions button, #refresh { width: 100%; }\n  .desktop-table { display: none; }\n  .mobile-cards { display: block; }\n}\n@media (prefers-reduced-motion: reduce) { *, *::before, *::after { transition: none !important; } }\n'

AGENDA_ADMIN_HTML = '<!doctype html>\n<html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Agenda editor · SessionBuddy</title><link rel="stylesheet" href="/product/assets/product.css?v=4"><link rel="stylesheet" href="/admin/agenda/assets/agenda.css?v=1"><script src="/admin/agenda/assets/agenda.js?v=1" defer></script></head>\n<body><a class="skip-link" href="#main">Skip to content</a><header><div class="shell agenda-header"><a href="/admin/programs">SessionBuddy</a><nav aria-label="Event administration"><a href="/admin/programs">Programs</a><a href="#agenda" aria-current="page">Agenda</a><a id="published-link" href="#">Published schedule</a></nav></div></header>\n<main id="main" class="shell" tabindex="-1"><section class="agenda-hero"><div><p class="eyebrow">Event operations</p><h1 id="event-title">Agenda editor</h1><p id="timezone" class="lede">Loading event schedule…</p></div><div class="revision"><span>Draft revision</span><strong id="revision">—</strong></div></section><div id="status" class="status" role="status" aria-live="polite">Checking your admin session…</div>\n<section class="agenda-toolbar" aria-labelledby="view-title"><div><p class="eyebrow">Layout</p><h2 id="view-title">View agenda</h2></div><fieldset><legend class="sr-only">Agenda view</legend><div class="segmented"><label><input type="radio" name="view" value="list" checked><span>List</span></label><label><input type="radio" name="view" value="day"><span>Day</span></label><label><input type="radio" name="view" value="week"><span>Week</span></label><label><input type="radio" name="view" value="track"><span>Track</span></label><label><input type="radio" name="view" value="room"><span>Room</span></label></div></fieldset><button id="refresh" class="secondary" type="button">Refresh</button><button id="publish" type="button">Publish agenda</button></section>\n<div class="agenda-layout"><aside class="panel" aria-labelledby="unscheduled-title"><h2 id="unscheduled-title">Unscheduled sessions</h2><p class="help">Drag a session into a group, or select Edit to schedule it with the keyboard form.</p><ul id="unscheduled" class="session-list"><li>Loading…</li></ul></aside><section id="agenda" class="panel board-panel" aria-labelledby="agenda-title" aria-busy="true"><div class="section-heading"><h2 id="agenda-title">Draft schedule</h2><span id="item-count" class="count">—</span></div><div id="conflict-banner" class="conflict" role="alert" tabindex="-1" hidden><strong>That change conflicts with the schedule.</strong><ul></ul></div><div id="board" class="agenda-board"></div><div id="empty" class="empty" hidden><strong>No sessions are scheduled.</strong><p>Add an accepted session from the unscheduled list.</p></div></section></div>\n<dialog id="editor" aria-labelledby="editor-title"><form id="editor-form"><div class="dialog-heading"><div><p class="eyebrow">Keyboard editor</p><h2 id="editor-title">Schedule session</h2></div><button id="close-editor" class="icon-button secondary" type="button" aria-label="Close schedule editor">×</button></div><div id="editor-errors" class="conflict" role="alert" tabindex="-1" hidden><strong>Review this schedule change.</strong><ul></ul></div><input name="item_id" type="hidden"><input name="session_id" type="hidden"><input name="version" type="hidden"><label>Session<input name="title" readonly></label><div class="form-grid"><label>Starts<input name="start_at" type="datetime-local" required></label><label>Ends<input name="end_at" type="datetime-local" required></label><label>Room<select name="room_id" required></select></label><label>Track<select name="track_id"><option value="">No track</option></select></label></div><p id="preview-state" class="preview-state" role="status" aria-live="polite">Change a field to check conflicts.</p><div class="actions"><button id="cancel-editor" class="secondary" type="button">Cancel</button><button id="save-item" type="submit">Save to draft</button></div></form></dialog></main></body></html>\n'

AGENDA_JS = '(() => {\n  "use strict";\n  const match = location.pathname.match(/^\\/admin\\/events\\/([^/]+)\\/agenda$/);\n  let eventId = "";\n  try { eventId = match ? decodeURIComponent(match[1]) : ""; } catch (_) { eventId = ""; }\n  if (!/^[A-Za-z0-9_.-]{1,128}$/.test(eventId)) eventId = "";\n  const state = { csrf: "", model: null, selected: null, previewTimer: null, previewToken: 0 };\n  const byId = (id) => document.getElementById(id);\n  const make = (tag, value, className) => { const node = document.createElement(tag); if (value !== undefined) node.textContent = value; if (className) node.className = className; return node; };\n  const key = () => `${crypto.randomUUID()}-${crypto.randomUUID()}`;\n\n  async function api(path, options = {}) {\n    const response = await fetch(path, { ...options, credentials: "same-origin", headers: { accept: "application/json", ...(options.headers || {}) } });\n    let body = null; try { body = await response.json(); } catch (_) { body = null; }\n    if (!response.ok) { const error = new Error(body?.error?.message || `Request failed (${response.status})`); error.status = response.status; error.body = body; throw error; }\n    return body;\n  }\n  function status(message, error = false) { byId("status").textContent = message; byId("status").classList.toggle("error", error); }\n  function format(value, options = {}) { try { return new Intl.DateTimeFormat(undefined, { timeZone: state.model.event.time_zone, ...options }).format(new Date(value)); } catch (_) { return "Date unavailable"; } }\n  function localInput(value) { const date = new Date(value); const shifted = new Date(date.getTime() - date.getTimezoneOffset() * 60000); return shifted.toISOString().slice(0, 16); }\n  function inputMillis(value) { return new Date(value).getTime(); }\n  function eventDate(value) { const parts = new Intl.DateTimeFormat("en-CA", { timeZone: state.model.event.time_zone, year: "numeric", month: "2-digit", day: "2-digit" }).formatToParts(new Date(value)); const fields = Object.fromEntries(parts.map((part) => [part.type, part.value])); return `${fields.year}-${fields.month}-${fields.day}`; }\n  function currentView() { return document.querySelector(\'input[name="view"]:checked\').value; }\n  function groupKey(item, view) {\n    if (view === "room") return item.room_name || "Unassigned room";\n    if (view === "track") return item.track_name || "No track";\n    if (view === "day") return format(item.start_at_ms, { weekday: "long", month: "short", day: "numeric" });\n    if (view === "week") {\n      const date = new Date(item.start_at_ms);\n      date.setUTCDate(date.getUTCDate() - date.getUTCDay());\n      return `Week of ${format(date.getTime(), { month: "short", day: "numeric", year: "numeric" })}`;\n    }\n    return "All sessions";\n  }\n  function card(item, scheduled = true) {\n    const node = make("li", undefined, "session-card"); node.dataset.itemId = item.id || ""; node.dataset.sessionId = item.session_id; node.draggable = true;\n    if (item.id?.startsWith("optimistic-")) node.classList.add("optimistic");\n    node.setAttribute("aria-label", `${item.title}. ${scheduled ? "Scheduled session; drag to move or use Edit." : "Unscheduled session; drag to schedule or use Edit."}`);\n    node.append(make("h3", item.title));\n    if (scheduled) node.append(make("p", `${format(item.start_at_ms, { hour: "numeric", minute: "2-digit" })}–${format(item.end_at_ms, { hour: "numeric", minute: "2-digit" })} · ${item.room_name}`, "scheduled-meta"));\n    const edit = make("button", scheduled ? "Edit" : "Schedule", "secondary"); edit.type = "button"; edit.addEventListener("click", () => openEditor(item)); node.append(edit);\n    node.addEventListener("dragstart", (event) => { state.selected = item; node.classList.add("dragging"); event.dataTransfer.effectAllowed = "move"; event.dataTransfer.setData("text/plain", item.id || item.session_id); });\n    node.addEventListener("dragend", () => { node.classList.remove("dragging"); document.querySelectorAll(".agenda-group").forEach((group) => group.classList.remove("preview-ok", "preview-conflict")); });\n    return node;\n  }\n  function render() {\n    const model = state.model; const view = currentView();\n    byId("event-title").textContent = model.event.name; byId("timezone").textContent = `Draft agenda · ${model.event.time_zone}`;\n    byId("revision").textContent = `v${model.revision.version} · ${model.revision.state}`;\n    byId("published-link").href = `/events/${encodeURIComponent(eventId)}/schedule`;\n    byId("item-count").textContent = String(model.items.length);\n    const unscheduled = byId("unscheduled"); unscheduled.replaceChildren();\n    if (!model.unscheduled_sessions.length) unscheduled.append(make("li", "All accepted sessions are scheduled.", "empty"));\n    model.unscheduled_sessions.forEach((item) => unscheduled.append(card(item, false)));\n    const groups = new Map(); model.items.forEach((item) => { const name = groupKey(item, view); if (!groups.has(name)) groups.set(name, []); groups.get(name).push(item); });\n    const board = byId("board"); board.replaceChildren(); byId("empty").hidden = model.items.length !== 0;\n    [...groups].sort(([left], [right]) => left.localeCompare(right)).forEach(([name, items]) => {\n      const section = make("section", undefined, "agenda-group"); section.dataset.group = name; section.tabIndex = 0; section.setAttribute("aria-label", `${name} drop target`);\n      section.append(make("h3", name)); const list = make("ul", undefined, "agenda-group-list");\n      items.sort((a, b) => a.start_at_ms - b.start_at_ms).forEach((item) => list.append(card(item))); section.append(list);\n      section.addEventListener("dragover", (event) => { event.preventDefault(); event.dataTransfer.dropEffect = "move"; });\n      section.addEventListener("dragenter", () => previewDrop(section, name, view));\n      section.addEventListener("drop", (event) => { event.preventDefault(); commitDrop(section, name, view); }); board.append(section);\n    });\n    byId("agenda").setAttribute("aria-busy", "false");\n  }\n  function candidateForGroup(item, name, view) {\n    const candidate = { item_id: item.id || null, session_id: item.session_id, start_at_ms: item.start_at_ms, end_at_ms: item.end_at_ms, room_id: item.room_id || state.model.rooms[0]?.id, track_id: item.track_id || null, version: item.version || 0, event_date: eventDate(item.start_at_ms) };\n    if (view === "room") candidate.room_id = state.model.rooms.find((room) => room.name === name)?.id || candidate.room_id;\n    if (view === "track") candidate.track_id = state.model.tracks.find((track) => track.name === name)?.id || null;\n    return candidate;\n  }\n  async function preview(candidate) { return api(`/api/v1/admin/events/${encodeURIComponent(eventId)}/agenda/preview`, { method: "POST", headers: { "content-type": "application/json", "x-csrf-token": state.csrf }, body: JSON.stringify(candidate) }); }\n  async function previewDrop(section, name, view) {\n    if (!state.selected?.start_at_ms) return;\n    try { const result = await preview(candidateForGroup(state.selected, name, view)); section.classList.toggle("preview-ok", result.valid); section.classList.toggle("preview-conflict", !result.valid); showConflicts(result.conflicts || []); } catch (_) { section.classList.add("preview-conflict"); }\n  }\n  async function commitDrop(section, name, view) {\n    if (!state.selected?.start_at_ms) { openEditor(state.selected); return; }\n    const candidate = candidateForGroup(state.selected, name, view); const before = structuredClone(state.model);\n    try { const check = await preview(candidate); if (!check.valid) { showConflicts(check.conflicts); section.classList.add("preview-conflict"); return; } optimistic(candidate); render(); await save(candidate); status("Agenda change saved."); }\n    catch (error) { state.model = before; render(); const restored = document.querySelector(`[data-item-id="${CSS.escape(candidate.item_id || "")}"]`); restored?.classList.add("rollback"); status(error.status === 409 ? "Schedule changed elsewhere or conflicts. Your move was rolled back." : "The move could not be saved and was rolled back.", true); }\n  }\n  function optimistic(candidate) { let item = state.model.items.find((value) => value.id === candidate.item_id); if (!item) { item = { ...state.selected, id: `optimistic-${candidate.session_id}`, version: 0 }; state.model.items.push(item); state.model.unscheduled_sessions = state.model.unscheduled_sessions.filter((value) => value.session_id !== candidate.session_id); } Object.assign(item, candidate); item.room_name = state.model.rooms.find((room) => room.id === candidate.room_id)?.name || item.room_name; item.track_name = state.model.tracks.find((track) => track.id === candidate.track_id)?.name || null; }\n  async function save(candidate) { const creating = !candidate.item_id; const path = creating ? `/api/v1/admin/events/${encodeURIComponent(eventId)}/agenda/items` : `/api/v1/admin/events/${encodeURIComponent(eventId)}/agenda/items/${encodeURIComponent(candidate.item_id)}`; const saved = await api(path, { method: creating ? "POST" : "PATCH", headers: { "content-type": "application/json", "x-csrf-token": state.csrf, "idempotency-key": key() }, body: JSON.stringify(candidate) }); await load(false); return saved; }\n  function options(select, values, selected, empty) { select.replaceChildren(); if (empty) select.add(new Option(empty, "")); values.forEach((value) => select.add(new Option(value.name, value.id))); select.value = selected || ""; }\n  function openEditor(item) { if (!item) return; state.selected = item; const form = byId("editor-form"); form.elements.item_id.value = item.id || ""; form.elements.session_id.value = item.session_id; form.elements.version.value = item.version || 0; form.elements.title.value = item.title; form.elements.start_at.value = item.start_at_ms ? localInput(item.start_at_ms) : ""; form.elements.end_at.value = item.end_at_ms ? localInput(item.end_at_ms) : ""; options(form.elements.room_id, state.model.rooms, item.room_id, "Choose room"); options(form.elements.track_id, state.model.tracks, item.track_id, "No track"); clearConflicts(); byId("preview-state").textContent = "Change a field to check conflicts."; byId("editor").showModal(); }\n  function formCandidate() { const form = byId("editor-form"); const start = inputMillis(form.elements.start_at.value); return { item_id: form.elements.item_id.value || null, session_id: form.elements.session_id.value, start_at_ms: start, end_at_ms: inputMillis(form.elements.end_at.value), room_id: form.elements.room_id.value, track_id: form.elements.track_id.value || null, version: Number(form.elements.version.value), event_date: eventDate(start) }; }\n  function clearConflicts() { byId("conflict-banner").hidden = true; byId("editor-errors").hidden = true; }\n  function showConflicts(conflicts, editor = false) { const panel = byId(editor ? "editor-errors" : "conflict-banner"); const list = panel.querySelector("ul"); list.replaceChildren(); conflicts.forEach((conflict) => list.append(make("li", conflict.message))); panel.hidden = conflicts.length === 0; if (conflicts.length) panel.focus(); }\n  function schedulePreview() { clearTimeout(state.previewTimer); const token = ++state.previewToken; state.previewTimer = setTimeout(async () => { const candidate = formCandidate(); if (!Number.isFinite(candidate.start_at_ms) || !Number.isFinite(candidate.end_at_ms) || candidate.start_at_ms >= candidate.end_at_ms || !candidate.room_id) { byId("preview-state").textContent = "Enter a valid start, end, and room."; byId("preview-state").className = "preview-state error"; return; } try { const result = await preview(candidate); if (token !== state.previewToken) return; showConflicts(result.conflicts || [], true); byId("preview-state").textContent = result.valid ? "No room or speaker conflicts found." : "Conflict found. Adjust the schedule before saving."; byId("preview-state").className = `preview-state ${result.valid ? "ok" : "error"}`; byId("save-item").disabled = !result.valid; } catch (_) { byId("preview-state").textContent = "Conflict preview unavailable. Saving is disabled."; byId("preview-state").className = "preview-state error"; byId("save-item").disabled = true; } }, 150); }\n  async function load(announce = true) { const model = await api(`/api/v1/admin/events/${encodeURIComponent(eventId)}/agenda`); state.model = model; render(); if (announce) status("Draft agenda loaded."); }\n  document.querySelectorAll(\'input[name="view"]\').forEach((input) => input.addEventListener("change", render));\n  byId("refresh").addEventListener("click", () => load().catch(() => status("Agenda could not be refreshed.", true)));\n  byId("publish").addEventListener("click", async () => {\n    const button = byId("publish"); button.disabled = true;\n    try {\n      await api(`/api/v1/admin/events/${encodeURIComponent(eventId)}/agenda/publish`, {\n        method: "POST", headers: { "content-type": "application/json", "x-csrf-token": state.csrf },\n        body: JSON.stringify({ revision_id: state.model.revision.id, version: state.model.revision.version })\n      });\n      await load(false); status("Agenda published. Calendar updates were queued for speakers.");\n    } catch (error) { status(error.status === 409 ? "This draft changed before publication. Refresh and review it again." : "The agenda could not be published.", true); }\n    finally { button.disabled = false; }\n  });\n  byId("editor-form").addEventListener("input", schedulePreview);\n  byId("editor-form").addEventListener("submit", async (event) => { event.preventDefault(); const candidate = formCandidate(); const before = structuredClone(state.model); byId("save-item").disabled = true; try { const check = await preview(candidate); if (!check.valid) { showConflicts(check.conflicts, true); return; } optimistic(candidate); byId("editor").close(); render(); await save(candidate); status("Session scheduled successfully."); } catch (error) { state.model = before; render(); status(error.status === 409 ? "The schedule changed or conflicts. Your edit was rolled back." : "The edit could not be saved and was rolled back.", true); } finally { byId("save-item").disabled = false; } });\n  ["close-editor", "cancel-editor"].forEach((id) => byId(id).addEventListener("click", () => byId("editor").close()));\n  async function initialize() { if (!eventId) { status("Invalid agenda link. Return to Programs and select an event.", true); return; } try { const session = await api("/api/v1/session"); state.csrf = session.csrf_token; try { await load(); } catch (error) { if (error.status !== 404) throw error; await api(`/api/v1/demo/agenda-context?event_id=${encodeURIComponent(eventId)}`, { method: "POST", headers: { "content-type": "application/json", "x-csrf-token": state.csrf } }); await load(); } } catch (error) { status(error.status === 401 ? "Sign in as an event administrator to edit this agenda." : "Agenda unavailable. For the local demo, initialize the speaker data first.", true); byId("agenda").setAttribute("aria-busy", "false"); } }\n  initialize();\n})();\n'

AGENDA_CSS = '.skip-link { position: fixed; top: -5rem; left: 1rem; z-index: 20; padding: .7rem 1rem; background: white; color: #173f9f; }.skip-link:focus{top:.5rem}.agenda-header{display:flex;justify-content:space-between;align-items:center}.agenda-header nav{display:flex;gap:.2rem}.agenda-header nav a{min-height:2.75rem;display:inline-flex;align-items:center;padding:.4rem .7rem;border-radius:.5rem;text-decoration:none}.agenda-header nav a[aria-current=page]{background:#34425e}.agenda-hero{display:flex;justify-content:space-between;align-items:end;gap:1rem;margin-bottom:1.25rem}.revision{display:grid;min-width:10rem;padding:1rem;border:1px solid #dce1eb;border-radius:.75rem;background:white}.revision span,.help{color:#59667c}.revision strong{font-size:1.25rem}.agenda-toolbar{display:flex;align-items:end;justify-content:space-between;gap:1rem;padding:1rem;border:1px solid #dce1eb;border-radius:.8rem;background:white}.agenda-toolbar h2{margin:.1rem 0}.agenda-toolbar fieldset{margin:0;padding:0;border:0}.segmented{display:flex;flex-wrap:wrap;gap:.25rem}.segmented label{margin:0}.segmented input{position:absolute;opacity:0;pointer-events:none}.segmented span{min-height:2.75rem;display:inline-flex;align-items:center;padding:.55rem .8rem;border:1px solid #aeb8ca;border-radius:.5rem;cursor:pointer}.segmented input:checked+span{border-color:#3159d9;background:#e9eeff;color:#274aa9;font-weight:750}.segmented input:focus-visible+span{outline:3px solid #e69b00;outline-offset:3px}.agenda-layout{display:grid;grid-template-columns:minmax(15rem,.35fr) minmax(0,1fr);gap:1.25rem;margin-top:1.25rem}.panel{padding:1.25rem;border:1px solid #dce1eb;border-radius:.9rem;background:white}.section-heading{display:flex;justify-content:space-between;gap:1rem;align-items:start}.count{height:max-content;padding:.2rem .6rem;border-radius:999px;background:#e9eeff;color:#274aa9;font-weight:750}.session-list{display:grid;gap:.65rem;margin:0;padding:0;list-style:none}.session-card{padding:.85rem;border:1px solid #dce1eb;border-radius:.65rem;background:white}.session-card[draggable=true]{cursor:grab}.session-card.dragging{opacity:.5}.session-card h3{margin:0 0 .3rem;font-size:1rem}.session-card p{margin:.25rem 0;color:#59667c}.session-card button{margin-top:.5rem}.agenda-board{display:grid;gap:1rem}.agenda-group{min-height:6rem;padding:.8rem;border:1px dashed #abb6c8;border-radius:.75rem;background:#f7f8fb}.agenda-group.preview-ok{border-color:#168253;background:#eef9f3}.agenda-group.preview-conflict{border-color:#b42318;background:#fff0ee}.agenda-group h3{margin:.1rem 0 .65rem}.agenda-group-list{display:grid;gap:.55rem;margin:0;padding:0;list-style:none}.scheduled-meta{font-size:.88rem}.conflict{margin:1rem 0;padding:1rem;border:1px solid #b42318;border-radius:.65rem;background:#fff0ee;color:#7a271a}.empty{padding:1rem;border-radius:.7rem;background:#f1f4fa}.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}dialog{width:min(42rem,calc(100% - 2rem));max-height:calc(100% - 2rem);padding:0;border:0;border-radius:1rem;box-shadow:0 1rem 4rem rgb(20 30 50 / 30%)}dialog::backdrop{background:rgb(10 20 35 / 55%)}dialog form{padding:1.4rem}.dialog-heading{display:flex;justify-content:space-between;gap:1rem}.icon-button{width:2.75rem;padding:0;font-size:1.5rem}.preview-state{padding:.7rem;border-left:.25rem solid #3159d9;background:#edf2ff}.preview-state.ok{border-color:#168253;background:#ebf8f1}.preview-state.error{border-color:#b42318;background:#fff0ee}.optimistic{opacity:.65}.rollback{outline:3px solid #b42318;outline-offset:3px}@media(max-width:48rem){.agenda-header,.agenda-hero,.agenda-toolbar{align-items:flex-start;flex-direction:column}.agenda-header{padding-block:.8rem}.agenda-header nav{width:100%;overflow-x:auto}.agenda-layout{grid-template-columns:1fr}.segmented{flex-wrap:nowrap;max-width:calc(100vw - 4rem);overflow-x:auto}.agenda-toolbar>button{width:100%}.form-grid{grid-template-columns:1fr}}@media(prefers-reduced-motion:reduce){*,:before,:after{scroll-behavior:auto!important;transition:none!important}}\n'

SCHEDULE_HTML = '<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Event schedule · SessionBuddy</title><link rel="stylesheet" href="/product/assets/product.css?v=4"><link rel="stylesheet" href="/schedule/assets/schedule.css?v=1"><script src="/schedule/assets/schedule.js?v=1" defer></script></head><body><a class="skip-link" href="#main">Skip to schedule</a><header><div class="shell"><strong>SessionBuddy</strong><a href="/speaker">Speaker portal</a></div></header><main id="main" class="shell" tabindex="-1"><p class="eyebrow">Published schedule</p><h1 id="title">Event schedule</h1><p id="timezone" class="lede">Loading…</p><div id="status" class="status" role="status" aria-live="polite">Loading published sessions…</div><nav class="schedule-filters" aria-label="Schedule views"><button data-view="list" aria-pressed="true">List</button><button data-view="day" class="secondary" aria-pressed="false">Day</button><button data-view="track" class="secondary" aria-pressed="false">Track</button><button data-view="room" class="secondary" aria-pressed="false">Room</button></nav><div id="schedule" class="schedule"></div><div id="empty" class="card" hidden>No sessions are published yet.</div></main></body></html>\n'

SCHEDULE_JS = '(() => { "use strict";\n  const match = location.pathname.match(/^\\/events\\/([^/]+)\\/schedule$/); let eventId = ""; try { eventId = match ? decodeURIComponent(match[1]) : ""; } catch (_) { eventId = ""; } if (!/^[A-Za-z0-9_.-]{1,128}$/.test(eventId)) eventId = "";\n  const state = { model: null, view: "list" }; const byId = (id) => document.getElementById(id); const make = (tag, value, className) => { const node = document.createElement(tag); if (value !== undefined) node.textContent = value; if (className) node.className = className; return node; };\n  function format(value, options) { try { return new Intl.DateTimeFormat(undefined, { timeZone: state.model.event.time_zone, ...options }).format(new Date(value)); } catch (_) { return "Date unavailable"; } }\n  function group(item) { if (state.view === "room") return item.room_name; if (state.view === "track") return item.track_name || "No track"; if (state.view === "day") return format(item.start_at_ms, { weekday: "long", month: "long", day: "numeric" }); return "All sessions"; }\n  function render() { const groups = new Map(); state.model.items.forEach((item) => { const key = group(item); if (!groups.has(key)) groups.set(key, []); groups.get(key).push(item); }); const root = byId("schedule"); root.replaceChildren(); byId("empty").hidden = state.model.items.length !== 0; [...groups].forEach(([name, items]) => { const section = make("section", undefined, "schedule-group"); section.append(make("h2", name)); const list = make("ol", undefined, "schedule-list"); items.sort((a,b) => a.start_at_ms-b.start_at_ms).forEach((item) => { const row = make("li", undefined, "schedule-item"); const time = make("time", `${format(item.start_at_ms,{hour:"numeric",minute:"2-digit"})}–${format(item.end_at_ms,{hour:"numeric",minute:"2-digit"})}`); time.dateTime = new Date(item.start_at_ms).toISOString(); const details = document.createElement("div"); details.append(make("h3", item.title), make("p", `${item.speaker_names.join(", ")} · ${item.room_name}${item.track_name ? ` · ${item.track_name}` : ""}`)); row.append(time, details); list.append(row); }); section.append(list); root.append(section); }); }\n  document.querySelectorAll("[data-view]").forEach((button) => button.addEventListener("click", () => { state.view = button.dataset.view; document.querySelectorAll("[data-view]").forEach((item) => { const active = item === button; item.setAttribute("aria-pressed", String(active)); item.classList.toggle("secondary", !active); }); render(); }));\n  async function load() { if (!eventId) throw new Error("Invalid schedule link"); const response = await fetch(`/api/v1/events/${encodeURIComponent(eventId)}/schedule`, { credentials:"same-origin", headers:{accept:"application/json"} }); const body = await response.json(); if (!response.ok) throw new Error(body?.error?.message || "Schedule unavailable"); state.model = body; byId("title").textContent = body.event.name; byId("timezone").textContent = `Times shown in ${body.event.time_zone}. Published revision ${body.revision.version}.`; byId("status").textContent = `${body.items.length} published session${body.items.length===1?"":"s"}.`; render(); }\n  load().catch((error) => { byId("status").textContent = error.message; byId("status").classList.add("error"); });\n})();\n'

